{"command":"cat > /tmp/probe.py << 'PY'
import subprocess, time, sys
def tmux(*args):
    return subprocess.run(["tmux"]+list(args), capture_output=True, text=True)
def cap(name="t", esc=False):
    args=["capture-pane","-p","-t",name]
    if esc: args.insert(1,"-e")
    r=tmux(*args)
    return r.stdout
def run(cmd, keys=[], w=80,h=24, wait=0.6, name="t"):
    tmux("kill-session","-t",name)
    tmux("new-session","-d","-s",name,"-x",str(w),"-y",str(h), cmd)
    time.sleep(wait)
    outs=[cap(name, esc=True)]
    for k in keys:
        # keys can be list for send-keys args
        if isinstance(k, (list,tuple)):
            tmux("send-keys","-t",name,*k)
        else:
            tmux("send-keys","-t",name,"-l",k)
        time.sleep(0.4)
        outs.append(cap(name, esc=True))
    tmux("kill-session","-t",name)
    return outs

if __name__=="__main__":
    import shlex
    cmd=sys.argv[1]
    keys=[]
    # remaining args as key specs separated by ;
    # use simple: each arg is tmux key name
    for k in sys.argv[2:]:
        keys.append((k,))
    outs=run(cmd, keys=keys)
    for i,o in enumerate(outs):
        print(f"=== step {i} ===")
        print(o)
        print(f"=== end {i} ===")
PY
python3 /tmp/probe.py "./executable testdata/test3.txt" Down Down PageDown End Home 2>&1 | head -n 200"}

