import subprocess, time, re
def tmux(*args): return subprocess.run(["tmux"]+list(args), capture_output=True, text=True)
def cap(name="t"):
    return tmux("capture-pane","-p","-t",name).stdout
def run_plain(cmd, keys=[], w=80,h=24, wait=0.6):
    name="t"; tmux("kill-session","-t",name)
    tmux("new-session","-d","-s",name,"-x",str(w),"-y",str(h), cmd)
    time.sleep(wait); outs=[cap(name)]
    for k in keys:
        if isinstance(k,(list,tuple)): tmux("send-keys","-t",name,*k)
        else: tmux("send-keys","-t",name,"-l",k)
        time.sleep(0.3); outs.append(cap(name))
    tmux("kill-session","-t",name); return outs
def summarize(outs):
    for i,o in enumerate(outs):
        lines=o.splitlines()
        # pad to 24
        print(f"--step{i} status:{lines[-1] if lines else ''!r} first3:{lines[:3]!r} lastcontent:{lines[-4:-1]!r}")
PY
