{"command":"cat > config.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"gopkg.in/yaml.v3"
)

// StyleSpec is a style definition from configuration or defaults.
type StyleSpec struct {
	Foreground     *string
	Background     *string
	UnderlineColor *string
	Bold           *bool
	Blink          *bool
	Dim            *bool
	Italic         *bool
	Underline      *bool
	Reverse        *bool
	UnderlineStyle *int
}

func strp(s string) *string { return &s }
func boolp(b bool) *bool    { return &b }
func intp(i int) *int       { return &i }

func (s StyleSpec) getFG(def string) string {
	if s.Foreground != nil {
		return *s.Foreground
	}
	return def
}

// Settings holds display/search settings that can be copied per document.
type Settings struct {
	TabWidth          int
	Header            int
	AlternateRows     bool
	ColumnMode        bool
	LineNumMode       bool
	WrapMode          bool
	ColumnDelimiter   string
	MarkStyleWidth    int
	HScrollWidth      string
	VScrollLines      int
	SectionDelimiter  string
	SectionHeader     bool
	SectionHeaderNum  int
	HideOtherSection  bool
	VerticalHeader    int
	HeaderColumn      int
	Ruler             int
	StatusLine        bool
	Plain             bool
	Converter         string
	ColumnRainbow     bool
	ColumnWidth       bool
	ShrinkColumn      bool
	RightAlignColumn  bool
	FixedColumn       bool
	SkipLines         int
	JumpTarget        string
	MultiColors       []string
	StyleAlternate    StyleSpec
	StyleHeader       StyleSpec
	StyleBody         StyleSpec
	StyleLineNumber   StyleSpec
	StyleSearch       StyleSpec
	StyleColumn       StyleSpec
	StyleMark         StyleSpec
	StyleSectionLine  StyleSpec
	StyleVerticalHdr  StyleSpec
	StyleRuler        StyleSpec
	StyleHeaderBorder StyleSpec
	StyleSectionBorder StyleSpec
	StyleVerticalBorder StyleSpec
	MultiColorStyles  []StyleSpec
	ColumnRainbowStyles []StyleSpec
	StyleJumpTarget   StyleSpec
	StyleOverStrike   StyleSpec
	StyleOverLine     StyleSpec
	ShowFilename      bool
	PromptInvert      bool
}

func defaultSettings() Settings {
	s := Settings{
		TabWidth:         8,
		WrapMode:         true,
		ColumnDelimiter:  ",",
		MarkStyleWidth:   1,
		HScrollWidth:     "10%",
		VScrollLines:     2,
		SectionHeaderNum: 1,
		StatusLine:       true,
		Converter:        "es",
		ShowFilename:     true,
	}
	s.StyleAlternate = StyleSpec{Background: strp("gray")}
	s.StyleHeader = StyleSpec{Bold: boolp(true)}
	s.StyleLineNumber = StyleSpec{Bold: boolp(true)}
	s.StyleSearch = StyleSpec{Reverse: boolp(true)}
	s.StyleColumn = StyleSpec{Reverse: boolp(true)}
	s.StyleMark = StyleSpec{Background: strp("darkgoldenrod")}
	s.StyleSectionLine = StyleSpec{Background: strp("slateblue")}
	s.StyleRuler = StyleSpec{Background: strp("#333333"), Foreground: strp("#CCCCCC"), Bold: boolp(true)}
	s.StyleVerticalBorder = StyleSpec{Background: strp("#c0c0c0")}
	mc := []string{"red", "aqua", "yellow", "fuchsia", "lime", "blue", "grey"}
	for _, c := range mc {
		s.MultiColorStyles = append(s.MultiColorStyles, StyleSpec{Foreground: strp(c)})
	}
	rb := []string{"white", "crimson", "aqua", "lightsalmon", "lime", "blue", "yellowgreen"}
	for _, c := range rb {
		s.ColumnRainbowStyles = append(s.ColumnRainbowStyles, StyleSpec{Foreground: strp(c)})
	}
	s.StyleJumpTarget = StyleSpec{Underline: boolp(true)}
	return s
}

// AppConfig is the whole loaded configuration.
type AppConfig struct {
	Settings          Settings
	QuitSmall         bool
	IsWriteOriginal   bool
	BeforeWriteOriginal int
	AfterWriteOriginal  int
	CaseSensitive     bool
	SmartCaseSensitive bool
	RegexpSearch      bool
	Incsearch         bool
	MemoryLimit       int
	MemoryLimitFile   int
	DisableMouse      bool
	DisableColumnCycle bool
	DisableStickyFollow bool
	ViewMode          string
	ClipboardMethod   string
	SetTerminalTitle  bool
	Debug             bool
	ShrinkChar        string
	KeyBind           map[string][]string
	Modes             map[string]map[string]interface{}
	ModeNames         []string // sorted, includes general
	usedFile          string
	decodeErrors      []string
}

func defaultAppConfig() *AppConfig {
	c := &AppConfig{
		Settings:        defaultSettings(),
		Incsearch:       true,
		MemoryLimit:     -1,
		MemoryLimitFile: 100,
		ShrinkChar:      "…",
		KeyBind:         defaultKeyBinds(),
		Modes:           map[string]map[string]interface{}{},
	}
	return c
}

// helpers to fetch case-insensitively from a generic map
func ciMap(m map[string]interface{}, key string) (interface{}, bool) {
	if v, ok := m[key]; ok {
		return v, true
	}
	lk := strings.ToLower(key)
	for k, v := range m {
		if strings.ToLower(k) == lk {
			return v, true
		}
	}
	return nil, false
}

func asMap(v interface{}) map[string]interface{} {
	if m, ok := v.(map[string]interface{}); ok {
		return m
	}
	return nil
}

func asSlice(v interface{}) []interface{} {
	if s, ok := v.([]interface{}); ok {
		return s
	}
	return nil
}

var decodeErrs []string

func errInt(path string) {
	decodeErrs = append(decodeErrs, fmt.Sprintf("'%s' cannot parse value as 'int': strconv.ParseInt: invalid syntax", path))
}
func errBool(path string) {
	decodeErrs = append(decodeErrs, fmt.Sprintf("'%s' cannot parse value as 'bool': strconv.ParseBool: invalid syntax", path))
}

func toInt(v interface{}, path string) (int, bool) {
	switch t := v.(type) {
	case int:
		return t, true
	case int64:
		return int(t), true
	case float64:
		return int(t), true
	case string:
		n, err := strconv.ParseInt(strings.TrimSpace(t), 10, 64)
		if err != nil {
			errInt(path)
			return 0, false
		}
		return int(n), true
	case bool:
		if t {
			return 1, true
		}
		return 0, true
	}
	errInt(path)
	return 0, false
}

func toBool(v interface{}, path string) (bool, bool) {
	switch t := v.(type) {
	case bool:
		return t, true
	case string:
		b, err := strconv.ParseBool(strings.TrimSpace(t))
		if err != nil {
			errBool(path)
			return false, false
		}
		return b, true
	case int:
		return t != 0, true
	case int64:
		return t != 0, true
	case float64:
		return t != 0, true
	}
	errBool(path)
	return false, false
}

func toString(v interface{}) (string, bool) {
	switch t := v.(type) {
	case string:
		return t, true
	case int:
		return strconv.Itoa(t), true
	case int64:
		return strconv.FormatInt(t, 10), true
	case float64:
		return strconv.FormatFloat(t, 'f', -1, 64), true
	case bool:
		return strconv.FormatBool(t), true
	}
	return "", false
}

func applyStyleSpec(dst *StyleSpec, m map[string]interface{}) {
	if m == nil {
		return
	}
	if v, ok := ciMap(m, "Foreground"); ok {
		if s, ok := toString(v); ok { dst.Foreground = &s }
	}
	if v, ok := ciMap(m, "Background"); ok {
		if s, ok := toString(v); ok { dst.Background = &s }
	}
	if v, ok := ciMap(m, "UnderlineColor"); ok {
		if s, ok := toString(v); ok { dst.UnderlineColor = &s }
	}
	for _, kv := range []struct{name string; ptr **bool}{
		{"Bold", &dst.Bold}, {"Blink", &dst.Blink}, {"Dim", &dst.Dim}, {"Italic", &dst.Italic}, {"Underline", &dst.Underline}, {"Reverse", &dst.Reverse},
	} {
		if v, ok := ciMap(m, kv.name); ok {
			if b, ok := toBool(v, kv.name); ok { *kv.ptr = &b }
		}
	}
	if v, ok := ciMap(m, "UnderlineStyle"); ok {
		if n, ok := toInt(v, "UnderlineStyle"); ok { dst.UnderlineStyle = &n }
	}
}

func applyStyleList(dst *[]StyleSpec, v interface{}) {
	items := asSlice(v)
	if items == nil {
		return
	}
	var out []StyleSpec
	for _, it := range items {
		var sp StyleSpec
		applyStyleSpec(&sp, asMap(it))
		out = append(out, sp)
	}
	if len(out) > 0 {
		*dst = out
	}
}

// applyGeneral applies fields present in m onto Settings. prefix used for error paths.
