	}
	if v, ok := ciMap(m, "TabWidth"); ok { if n, ok := toInt(v, p("TabWidth")); ok { s.TabWidth = n } }
	if v, ok := ciMap(m, "Header"); ok { if n, ok := toInt(v, p("Header")); ok { s.Header = n } }
