	if v, ok := ciMap(m, "SectionHeaderNum"); ok { if n, ok := toInt(v, p("SectionHeaderNum")); ok { s.SectionHeaderNum = n } }
	if v, ok := ciMap(m, "HideOtherSection"); ok { if b, ok := toBool(v, p("HideOtherSection")); ok { s.HideOtherSection = b } }
	if v, ok := ciMap(m, "VerticalHeader"); ok { if n, ok := toInt(v, p("VerticalHeader")); ok { s.VerticalHeader = n } }
	if v, ok := ciMap(m, "HeaderColumn"); ok { if n, ok := toInt(v, p("HeaderColumn")); ok { s.HeaderColumn = n } }
	if v, ok := ciMap(m, "Converter"); ok { if str, ok := toString(v); ok { s.Converter = str } }
	if v, ok := ciMap(m, "ColumnRainbow"); ok { if b, ok := toBool(v, p("ColumnRainbow")); ok { s.ColumnRainbow = b } }
	if v, ok := ciMap(m, "ColumnWidth"); ok { if b, ok := toBool(v, p("ColumnWidth")); ok { s.ColumnWidth = b } }
	if v, ok := ciMap(m, "Ruler"); ok { if n, ok := toInt(v, p("Ruler")); ok { s.Ruler = n } }
	if v, ok := ciMap(m, "StatusLine"); ok { if b, ok := toBool(v, p("StatusLine")); ok { s.StatusLine = b } }
	// Prompt
	if v, ok := ciMap(m, "Prompt"); ok {
		if pm := asMap(v); pm != nil {
			if nv, ok := ciMap(pm, "Normal"); ok {
				if nm := asMap(nv); nm != nil {
