// helpers to fetch case-insensitively from a generic map
func ciMap(m map[string]interface{}, key string) (interface{}, bool) {
	if v, ok := m[key]; ok {
		return v, true
	}
	lk := strings.ToLower(key)
	for k, v := range m {
		if strings.ToLower(k) == lk {
			return v, true
		}
	}
	return nil, false
}

func asMap(v interface{}) map[string]interface{} {
	if m, ok := v.(map[string]interface{}); ok {
		return m
	}
	return nil
}

func asSlice(v interface{}) []interface{} {
	if s, ok := v.([]interface{}); ok {
		return s
	}
	return nil
}

var decodeErrs []string

func errInt(path string) {
	decodeErrs = append(decodeErrs, fmt.Sprintf("'%s' cannot parse value as 'int': strconv.ParseInt: invalid syntax", path))
}
func errBool(path string) {
	decodeErrs = append(decodeErrs, fmt.Sprintf("'%s' cannot parse value as 'bool': strconv.ParseBool: invalid syntax", path))
}

func toInt(v interface{}, path string) (int, bool) {
	switch t := v.(type) {
	case int:
		return t, true
	case int64:
		return int(t), true
	case float64:
		return int(t), true
	case string:
		n, err := strconv.ParseInt(strings.TrimSpace(t), 10, 64)
		if err != nil {
			errInt(path)
			return 0, false
		}
		return int(n), true
	case bool:
		if t {
			return 1, true
		}
		return 0, true
	}
	errInt(path)
	return 0, false
}

func toBool(v interface{}, path string) (bool, bool) {
	switch t := v.(type) {
	case bool:
		return t, true
	case string:
		b, err := strconv.ParseBool(strings.TrimSpace(t))
		if err != nil {
			errBool(path)
			return false, false
		}
		return b, true
	case int:
		return t != 0, true
	case int64:
		return t != 0, true
	case float64:
		return t != 0, true
	}
	errBool(path)
	return false, false
}

func toString(v interface{}) (string, bool) {
	switch t := v.(type) {
	case string:
		return t, true
	case int:
		return strconv.Itoa(t), true
	case int64:
		return strconv.FormatInt(t, 10), true
	case float64:
		return strconv.FormatFloat(t, 'f', -1, 64), true
	case bool:
		return strconv.FormatBool(t), true
	}
	return "", false
}

func applyStyleSpec(dst *StyleSpec, m map[string]interface{}) {
	if m == nil {
		return
