// configFileResult mirrors viper-ish loading outcomes.
type configLoad struct {
	cfg       *AppConfig
	readErr   error
	notFound  bool // search-path not found
	used      string
	decode    []string
	searchDir string
}

func configSearchDir() string {
	if x := os.Getenv("XDG_CONFIG_HOME"); x != "" {
		return filepath.Join(x, "ov")
	}
	home, _ := os.UserHomeDir()
	return filepath.Join(home, ".config", "ov")
}

func loadConfig(explicit string, cliDebug bool) configLoad {
	cfg := defaultAppConfig()
	res := configLoad{cfg: cfg}
	searchDir := configSearchDir()
	res.searchDir = searchDir
	var data []byte
	var used string
	var explicitPath bool
	if explicit != "" {
		explicitPath = true
		used = explicit
		// viper: unsupported type based on extension
		ext := strings.TrimPrefix(filepath.Ext(explicit), ".")
		if ext != "yaml" && ext != "yml" && ext != "json" && ext != "toml" && ext != "ini" && ext != "properties" && ext != "props" && ext != "prop" && ext != "env" && ext != "dotenv" && ext != "hcl" && ext != "tfvars" {
			res.readErr = fmt.Errorf("Unsupported Config Type %q", ext)
			res.used = used
			cfg.usedFile = used
			finishDebug(&res, cliDebug)
			return res
		}
		b, err := os.ReadFile(explicit)
		if err != nil {
			res.readErr = err
			res.used = used
			cfg.usedFile = used
			finishDebug(&res, cliDebug)
			return res
		}
		data = b
	} else {
		// search
		found := ""
		for _, ext := range []string{"yaml", "yml", "json", "toml"} {
			p := filepath.Join(searchDir, "config."+ext)
			if _, err := os.Stat(p); err == nil {
				found = p
				break
			}
		}
		if found == "" {
			res.notFound = true
			res.readErr = fmt.Errorf("Config File %q Not Found in %q", "config", []string{searchDir})
			// viper formats []string slice with brackets; custom below in caller
			res.used = ""
			finishDebug(&res, cliDebug)
			return res
		}
		b, err := os.ReadFile(found)
		if err != nil {
			res.readErr = err
			res.used = found
			cfg.usedFile = found
			finishDebug(&res, cliDebug)
			return res
		}
		data = b
		used = found
	}
	res.used = used
	cfg.usedFile = used
	_ = explicitPath
	// parse yaml
	decodeErrs = nil
	var generic interface{}
	if len(data) > 0 {
		if err := yaml.Unmarshal(data, &generic); err != nil {
			res.readErr = fmt.Errorf("While parsing config: %s", err.Error())
			finishDebug(&res, cliDebug)
			return res
		}
	}
	root := asMap(generic)
	if root != nil {
		applyRootConfig(cfg, root)
	}
	res.decode = append([]string{}, decodeErrs...)
	cfg.decodeErrors = res.decode
	finishDebug(&res, cliDebug)
	return res
}

func finishDebug(res *configLoad, cliDebug bool) {
	cfg := res.cfg
	effectiveDebug := cliDebug || cfg.Debug
	// Print read error
	if res.readErr != nil {
		if res.notFound {
			if effectiveDebugButBeforeParse(cliDebug, cfg) {
				// printed below
			}
		}
		_ = effectiveDebug
	}
	_ = res
}

func effectiveDebugButBeforeParse(cli bool, cfg *AppConfig) bool { return cli || cfg.Debug }

// reportConfig prints the viper-like messages to stderr. Called from run.
func (cl configLoad) report(cliDebug bool) {
	cfg := cl.cfg
	debug := cliDebug || cfg.Debug
	if cl.readErr != nil {
		should := true
		if cl.notFound && !debug {
			should = false
			// however if the config itself could not be read, Debug unknown; cli flag decides (already in debug)
		}
		if should {
			if cl.notFound {
				fmt.Fprintf(os.Stderr, "failed to read config file: Config File \"config\" Not Found in \"[%s]\"\n", cl.searchDir)
			} else {
				fmt.Fprintf(os.Stderr, "failed to read config file: %s\n", cl.readErr.Error())
			}
		}
	}
	if len(cl.decode) > 0 {
		fmt.Fprintf(os.Stderr, "decoding failed due to the following error(s):\n\n%s\n", strings.Join(cl.decode, "\n"))
	}
	if debug {
		if cl.used != "" {
			fmt.Fprintf(os.Stderr, "Using config file: %s\n", cl.used)
		} else {
			fmt.Fprintf(os.Stderr, "config file not found\n")
		}
	}
}

func applyRootConfig(cfg *AppConfig, root map[string]interface{}) {
	if v, ok := ciMap(root, "QuitSmall"); ok { if b, ok := toBool(v, "QuitSmall"); ok { cfg.QuitSmall = b } }
	if v, ok := ciMap(root, "IsWriteOriginal"); ok { if b, ok := toBool(v, "IsWriteOriginal"); ok { cfg.IsWriteOriginal = b } }
