	if v, ok := ciMap(root, "AfterWriteOriginal"); ok { if n, ok := toInt(v, "AfterWriteOriginal"); ok { cfg.AfterWriteOriginal = n } }
	if v, ok := ciMap(root, "CaseSensitive"); ok { if b, ok := toBool(v, "CaseSensitive"); ok { cfg.CaseSensitive = b } }
	if v, ok := ciMap(root, "SmartCaseSensitive"); ok { if b, ok := toBool(v, "SmartCaseSensitive"); ok { cfg.SmartCaseSensitive = b } }
	if v, ok := ciMap(root, "RegexpSearch"); ok { if b, ok := toBool(v, "RegexpSearch"); ok { cfg.RegexpSearch = b } }
	if v, ok := ciMap(root, "Incsearch"); ok { if b, ok := toBool(v, "Incsearch"); ok { cfg.Incsearch = b } }
	if v, ok := ciMap(root, "IncSearch"); ok { if b, ok := toBool(v, "IncSearch"); ok { cfg.Incsearch = b } }
	if v, ok := ciMap(root, "MemoryLimit"); ok { if n, ok := toInt(v, "MemoryLimit"); ok { cfg.MemoryLimit = n } }
	if v, ok := ciMap(root, "MemoryLimitFile"); ok { if n, ok := toInt(v, "MemoryLimitFile"); ok { cfg.MemoryLimitFile = n } }
	if v, ok := ciMap(root, "DisableMouse"); ok { if b, ok := toBool(v, "DisableMouse"); ok { cfg.DisableMouse = b } }
	if v, ok := ciMap(root, "DisableColumnCycle"); ok { if b, ok := toBool(v, "DisableColumnCycle"); ok { cfg.DisableColumnCycle = b } }
	if v, ok := ciMap(root, "DisableStickyFollow"); ok { if b, ok := toBool(v, "DisableStickyFollow"); ok { cfg.DisableStickyFollow = b } }
	if v, ok := ciMap(root, "ViewMode"); ok { if s, ok := toString(v); ok { cfg.ViewMode = s } }
	if v, ok := ciMap(root, "ClipboardMethod"); ok { if s, ok := toString(v); ok { cfg.ClipboardMethod = s } }
	if v, ok := ciMap(root, "SetTerminalTitle"); ok { if b, ok := toBool(v, "SetTerminalTitle"); ok { cfg.SetTerminalTitle = b } }
	if v, ok := ciMap(root, "Debug"); ok { if b, ok := toBool(v, "Debug"); ok { cfg.Debug = b } }
	if v, ok := ciMap(root, "ShrinkChar"); ok { if s, ok := toString(v); ok && s != "" { cfg.ShrinkChar = s } }
	// top-level overstrike styles (from ov.yaml legacy layout)
	if v, ok := ciMap(root, "StyleOverStrike"); ok { applyStyleSpec(&cfg.Settings.StyleOverStrike, asMap(v)) }
	if v, ok := ciMap(root, "StyleOverLine"); ok { applyStyleSpec(&cfg.Settings.StyleOverLine, asMap(v)) }
	if v, ok := ciMap(root, "General"); ok {
		if gm := asMap(v); gm != nil {
			applyGeneral(&cfg.Settings, gm, "General")
		}
	}
	if v, ok := ciMap(root, "KeyBind"); ok {
		if km := asMap(v); km != nil {
			for action, val := range km {
				var keys []string
				for _, item := range asSlice(val) {
					if s, ok := toString(item); ok {
						keys = append(keys, s)
					}
				}
				if keys != nil {
					cfg.KeyBind[strings.ToLower(action)] = keys
				}
			}
		}
	}
	if v, ok := ciMap(root, "Mode"); ok {
		if mm := asMap(v); mm != nil {
			for name, mv := range mm {
				if m := asMap(mv); m != nil {
					cfg.Modes[name] = m
				}
			}
		}
	}
}

func (cfg *AppConfig) modeNames() []string {
	names := []string{"general"}
	for n := range cfg.Modes {
		if n != "general" {
			names = append(names, n)
		}
	}
	sort.Strings(names)
	// ensure general present in sorted position; sort already puts it alphabetically
	// If modes contains general only once
	return names
}

// settingsForMode returns settings with named mode applied (mode must exist).
func (cfg *AppConfig) settingsForMode(base Settings, name string) (Settings, bool) {
	m, ok := cfg.Modes[name]
	if !ok {
		return base, false
	}
	s := base
	applyGeneral(&s, m, "")
	// Mode may have Style at top-level of mode (same as General Style handling in applyGeneral)
	return s, true
}
