func splitLines(data []byte) []string {
	s := string(data)
	s = strings.ReplaceAll(s, "\r\n", "\n")
	// also lone \r? original strips? keep as control conversion later if remaining
	if s == "" {
		return nil
	}
	lines := strings.Split(s, "\n")
	if strings.HasSuffix(s, "\n") {
		lines = lines[:len(lines)-1]
	}
	// trim trailing \r per line (CRLF already handled, but lone \r\n case)
	for i := range lines {
		lines[i] = strings.TrimSuffix(lines[i], "\r")
	}
	return lines
}

func decompressIfNeeded(data []byte, skipExtract bool) []byte {
	if skipExtract || len(data) < 4 {
		return data
	}
	out, ok := tryDecompress(data)
	if ok {
		return out
	}
	return data
}

func tryDecompress(data []byte) ([]byte, bool) {
	// gzip
	if len(data) >= 2 && data[0] == 0x1f && data[1] == 0x8b {
		r, err := gzip.NewReader(bytes.NewReader(data))
		if err != nil {
			return nil, false
		}
		b, err := io.ReadAll(r)
		if err == nil || len(b) > 0 {
			return b, true
		}
		return nil, false
	}
	// bzip2
	if len(data) >= 3 && data[0] == 'B' && data[1] == 'Z' && data[2] == 'h' {
		r := bzip2.NewReader(bytes.NewReader(data))
		b, err := io.ReadAll(r)
		if err == nil || len(b) > 0 {
			return b, true
		}
		return nil, false
	}
	// xz
	if len(data) >= 6 && bytes.Equal(data[:6], []byte{0xfd, '7', 'z', 'X', 'Z', 0}) {
		b, err := xzDecompress(data)
		if err == nil {
			return b, true
		}
		return nil, false
	}
	// zstd
	if len(data) >= 4 && data[0] == 0x28 && data[1] == 0xb5 && data[2] == 0x2f && data[3] == 0xfd {
		b, err := zstdDecompress(data)
		if err == nil {
			return b, true
		}
		return nil, false
	}
	// lz4 frame
	if len(data) >= 4 && data[0] == 0x04 && data[1] == 0x22 && data[2] == 0x4d && data[3] == 0x18 {
		b, err := lz4FrameDecompress(data)
		if err == nil {
			return b, true
		}
		return nil, false
	}
	return nil, false
}

