// parse line into cells according to converter/plain settings (without tab expansion)
func parseLineCells(raw string, s Settings) []Cell {
	converter := s.Converter
	if converter != "raw" && converter != "align" && converter != "es" {
		converter = "es"
	}
	if converter == "raw" {
		// Show escape sequences literally.
		var cells []Cell
		for _, r := range stringToRunes(raw) {
			if r == 0x1b {
				cells = append(cells, Cell{R: '^', Width: 1}, Cell{R: '[', Width: 1})
			} else if r == '\t' {
				cells = append(cells, Cell{R: '\t', Width: 0})
			} else if r == '\b' {
				// handled similar to overstrike-ish: keep as control -> represent?
				cells = append(cells, Cell{R: '\b', Width: 0})
			} else {
				cells = append(cells, Cell{R: r, Width: runeDisplayWidth(r)})
			}
		}
		return applyOverstrike(cells, s)
	}
	// es / align / plain
	plain := s.Plain
	var cells []Cell
	style := tcell.StyleDefault
	if !plain {
		// base body style
		style = styleFromSpec(s.StyleBody, style)
	}
	runes := stringToRunes(raw)
	i := 0
	for i < len(runes) {
		r := runes[i]
		if r == 0x1b && i+1 < len(runes) && runes[i+1] == '[' {
			// CSI sequence up to final byte 0x40-0x7e
			j := i + 2
			var params []rune
			for j < len(runes) && !(runes[j] >= 0x40 && runes[j] <= 0x7e) {
				params = append(params, runes[j])
				j++
			}
			if j < len(runes) {
				final := runes[j]
				if final == 'm' && !plain {
					style = applySGR(style, string(params))
				}
				i = j + 1
				continue
			}
			i = len(runes)
			continue
		}
		if r == 0x1b {
			// skip esc and maybe following char
			i++
			continue
		}
		st := style
		if plain {
			st = tcell.StyleDefault
		}
		cells = append(cells, Cell{R: r, Width: runeDisplayWidth(r), Style: st})
		i++
	}
	return applyOverstrike(cells, s)
}

func stringToRunes(s string) []rune {
	var out []rune
	for len(s) > 0 {
		r, size := utf8.DecodeRuneInString(s)
