		}
		if r == 0 {
			out = append(out, ' ')
			s = s[size:]
			continue
		}
		out = append(out, r)
		s = s[size:]
	}
	return out
}

func runeDisplayWidth(r rune) int {
	if r == '\t' || r == '\b' {
		return 0
	}
	if r < 0x20 {
		return 2 // ^X representation handled elsewhere? map to space-ish
	}
	w := runewidth.RuneWidth(r)
	if w == 0 {
		return 1
	}
	return w
}

func applyOverstrike(cells []Cell, s Settings) []Cell {
	if !containsBackspace(cells) {
		// assign default width/styles already; handle control runes
		return sanitizeControls(cells)
	}
	// build cell positions
	var out []Cell
	pos := 0 // index in out
	for _, c := range cells {
		if c.R == '\b' {
			if pos > 0 {
				pos--
			}
			continue
		}
		if pos < len(out) {
			existing := out[pos]
			if existing.R == '_' && c.R != '_' {
				st := existing.Style
				// overline style
				st = styleFromSpec(s.StyleOverLine, st)
				// If overline spec empty (not configured), original still underlines? With no config default empty - matches observed without config no underline.
				// Actually observed without config: B had no underline. So only apply spec if it has any attribute set.
				if !specIsEmpty(s.StyleOverLine) {
					c.Style = st
				} else {
					c.Style = existing.Style
					// keep new char style? use its own
					c.Style = c.Style
				}
				out[pos] = c
			} else if existing.R == c.R {
				st := c.Style
				if !specIsEmpty(s.StyleOverStrike) {
					st = styleFromSpec(s.StyleOverStrike, st)
				}
				c.Style = st
				out[pos] = c
			} else {
				// overwrite
				out[pos] = c
			}
			pos++
		} else {
			out = append(out, c)
			pos++
		}
	}
	return sanitizeControls(out)
}

func specIsEmpty(sp StyleSpec) bool {
	return sp.Foreground == nil && sp.Background == nil && sp.UnderlineColor == nil && sp.Bold == nil && sp.Blink == nil && sp.Dim == nil && sp.Italic == nil && sp.Underline == nil && sp.Reverse == nil && sp.UnderlineStyle == nil
}

func containsBackspace(cells []Cell) bool {
	for _, c := range cells {
		if c.R == '\b' {
			return true
		}
	}
	return false
}

func sanitizeControls(cells []Cell) []Cell {
	out := cells[:]
	for i, c := range out {
		if c.R < 0x20 && c.R != '\t' {
			// represent as ^X ? original displays some ... for DEL etc replace with ?
			// For CR inside line etc.
			out[i].R = '?'
			out[i].Width = 1
		}
		if c.R == 0x7f {
			out[i].R = '?'
			out[i].Width = 1
		}
	}
	return out
}

// expand tabs and produce cells with explicit positions
func expandTabs(cells []Cell, tabWidth int) []Cell {
	if tabWidth <= 0 {
		tabWidth = 8
	}
	var out []Cell
	pos := 0
	for _, c := range cells {
		if c.R == '\t' {
			n := tabWidth - (pos % tabWidth)
			for k := 0; k < n; k++ {
				out = append(out, Cell{R: ' ', Width: 1, Style: c.Style})
				pos++
			}
			continue
		}
		out = append(out, c)
		pos += c.Width
		if c.Width == 0 {
			// combining etc keep pos
		}
	}
	return out
}

func cellsText(cells []Cell) string {
	var b strings.Builder
	for _, c := range cells {
		b.WriteRune(c.R)
	}
	return b.String()
}

func cellsWidth(cells []Cell) int {
	w := 0
	for _, c := range cells {
		w += c.Width
	}
	return w
}
EOF"}

