package main

import (
	"encoding/binary"
	"errors"
)

func lz4BlockDecompress(src []byte, dstCap int) ([]byte, error) {
	dst := make([]byte, 0, dstCap)
	i := 0
	for i < len(src) {
		token := src[i]
		i++
		litLen := int(token >> 4)
		if litLen == 15 {
			for {
				if i >= len(src) { return nil, errors.New("lz4 bad") }
				b := src[i]; i++
				litLen += int(b)
				if b != 255 { break }
			}
		}
		if i+litLen > len(src) { return nil, errors.New("lz4 lit overflow") }
		dst = append(dst, src[i:i+litLen]...)
		i += litLen
		if i >= len(src) { break }
		if i+2 > len(src) { return nil, errors.New("lz4 offset") }
		offset := int(binary.LittleEndian.Uint16(src[i:]))
		i += 2
		if offset == 0 || offset > len(dst) { return nil, errors.New("lz4 bad offset") }
		matchLen := int(token & 0x0f)
		if matchLen == 15 {
			for {
				if i >= len(src) { return nil, errors.New("lz4 bad") }
				b := src[i]; i++
				matchLen += int(b)
				if b != 255 { break }
			}
		}
		matchLen += 4
		start := len(dst) - offset
		for k := 0; k < matchLen; k++ {
			dst = append(dst, dst[start+k])
		}
	}
	return dst, nil
}

func lz4FrameDecompress(data []byte) ([]byte, error) {
	if len(data) < 7 {
		return nil, errors.New("lz4 short")
	}
	// magic already checked
	pos := 4
	flg := data[pos]; pos++
	// BD
	pos++ // bd
	// content size?
	hasContentSize := (flg >> 3) & 1
	hasChecksum := (flg >> 2) & 1
	hasBlockChecksum := (flg >> 4) & 1
	// hasBlockIndependence := (flg >> 5) & 1
	if hasContentSize == 1 {
		pos += 8
	}
	// dictID
	if (flg & 1) == 1 {
		pos += 4
	}
	pos++ // HC
	var out []byte
	for {
		if pos+4 > len(data) { return nil, errors.New("lz4 block header") }
		blockSize := int(binary.LittleEndian.Uint32(data[pos:]))
		pos += 4
		if blockSize == 0 { break }
		uncompressedFlag := blockSize & 0x80000000
		blockSize &^= 0x80000000
		if pos+blockSize > len(data) { return nil, errors.New("lz4 block size") }
		block := data[pos:pos+blockSize]
		pos += blockSize
		if hasBlockChecksum == 1 { pos += 4 }
		if uncompressedFlag != 0 {
			out = append(out, block...)
		} else {
			dec, err := lz4BlockDecompress(block, blockSize*255+10)
			if err != nil { return nil, err }
			out = append(out, dec...)
		}
	}
	_ = hasChecksum
	return out, nil
}
