			style = style.Background(tcell.PaletteColor(n - 40))
		case n == 49:
			style = style.Background(tcell.ColorDefault)
		case n >= 90 && n <= 97:
			style = style.Foreground(tcell.PaletteColor(n - 90 + 8))
		case n >= 100 && n <= 107:
			style = style.Background(tcell.PaletteColor(n - 100 + 8))
		case n == 38 || n == 48 || n == 58:
			isFG := n != 48
			isUL := n == 58
			if i+1 < len(nums) && nums[i+1] == 5 && i+2 < len(nums) {
				c := tcell.PaletteColor(nums[i+2])
				if isUL {
					style = style.UnderlineColor(c)
				} else if isFG {
					style = style.Foreground(c)
				} else {
					style = style.Background(c)
				}
				i += 2
			} else if i+1 < len(nums) && nums[i+1] == 2 && i+4 < len(nums) {
				c := tcell.NewRGBColor(int32(nums[i+2]), int32(nums[i+3]), int32(nums[i+4]))
				if isUL {
					style = style.UnderlineColor(c)
				} else if isFG {
					style = style.Foreground(c)
				} else {
					style = style.Background(c)
				}
				i += 4
			}
		}
	}
	return style
}
