import "C"
import (
	"errors"
	"unsafe"
)

func zstdDecompress(data []byte) ([]byte, error) {
	var out *C.uchar
	var outSize C.size_t
	rc := C.zstd_all((*C.uchar)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &out, &outSize)
	if rc != 0 {
		return nil, errors.New("zstd decompress failed")
	}
	defer C.free(unsafe.Pointer(out))
	return C.GoBytes(unsafe.Pointer(out), C.int(outSize)), nil
}

func xzDecompress(data []byte) ([]byte, error) {
	var out *C.uchar
	var outSize C.size_t
	rc := C.xz_all((*C.uchar)(unsafe.Pointer(&data[0])), C.size_t(len(data)), &out, &outSize)
	if rc != 0 {
		return nil, errors.New("xz decompress failed")
	}
	defer C.free(unsafe.Pointer(out))
	return C.GoBytes(unsafe.Pointer(out), C.int(outSize)), nil
}
