{"command":"cat > vis.go <<'EOF'
package main

import (
	"fmt"
	"regexp"
	"strings"

	"github.com/gdamore/tcell/v2"
)

// fieldRange in cell coordinates of a full (unwrapped) line
type fieldRange struct {
	start, end int // cell index start, end exclusive (in rune cells, not display width? use cell index)
}

func splitFields(text string, delim string) []string {
	if delim == "" {
		return []string{text}
	}
	var fields []string
	rest := text
	for {
		// quote handling at field start
		if strings.HasPrefix(rest, "\"") {
			// find closing quote
			idx := strings.Index(rest[1:], "\"")
			if idx >= 0 {
				endQuote := 1 + idx + 1 // after closing quote
				// expect delimiter after quote
				if strings.HasPrefix(rest[endQuote:], delim) {
					fields = append(fields, rest[:endQuote])
					rest = rest[endQuote+len(delim):]
					continue
				}
				// no delimiter: whole rest is field (fallthrough to normal)
			}
		}
		idx := strings.Index(rest, delim)
		if idx < 0 {
			fields = append(fields, rest)
			break
		}
		fields = append(fields, rest[:idx])
		rest = rest[idx+len(delim):]
	}
	return fields
}

func splitFieldsRange(cells []Cell, delim string) []fieldRange {
	if delim == "" || len(cells) == 0 {
		return []fieldRange{{0, len(cells)}}
	}
	text := cellsText(cells)
	// Use text-based split then map rune positions to cell indices (1 rune per cell in our model except wide?)
	fields := splitFields(text, delim)
	var ranges []fieldRange
	pos := 0 // rune index == cell index (cells are one per rune except tabs expanded to multiple spaces; text runes count = cells)
	for i, f := range fields {
		start := pos
		end := pos + len([]rune(f))
		ranges = append(ranges, fieldRange{start, end})
		pos = end
		if i < len(fields)-1 {
			pos += len([]rune(delim))
		}
	}
	return ranges
}

// build aligned cells for all lines; returns per effective-line cells
func (d *Document) buildFullCells(width int) [][]Cell {
	s := d.Settings
	n := d.effCount()
	full := make([][]Cell, n)
	// first pass: base cells expanded tabs (unless align will handle)
	base := make([][]Cell, n)
	for i := 0; i < n; i++ {
		dl := d.effLine(i)
		if dl == nil {
			continue
		}
		cells := parseLineCells(dl.Raw, s)
		base[i] = cells
	}
	if s.Converter == "align" {
		// compute widths per column, using text after removing escapes but before tab expansion?
		// Expand tabs per line first for width calc with placeholder? Use tab expansion.
		expanded := make([][]Cell, n)
		for i := range base {
			expanded[i] = expandTabs(base[i], s.TabWidth)
		}
		// compute field ranges per line
		maxCols := 0
		rangesPerLine := make([][]fieldRange, n)
		for i, cells := range expanded {
			r := splitFieldsRange(cells, s.ColumnDelimiter)
			rangesPerLine[i] = r
