		if idx < 0 {
			fields = append(fields, rest)
			break
		}
		fields = append(fields, rest[:idx])
		rest = rest[idx+len(delim):]
	}
	return fields
}

func splitFieldsRange(cells []Cell, delim string) []fieldRange {
	if delim == "" || len(cells) == 0 {
		return []fieldRange{{0, len(cells)}}
	}
	text := cellsText(cells)
	// Use text-based split then map rune positions to cell indices (1 rune per cell in our model except wide?)
	fields := splitFields(text, delim)
	var ranges []fieldRange
	pos := 0 // rune index == cell index (cells are one per rune except tabs expanded to multiple spaces; text runes count = cells)
	for i, f := range fields {
		start := pos
		end := pos + len([]rune(f))
		ranges = append(ranges, fieldRange{start, end})
		pos = end
		if i < len(fields)-1 {
			pos += len([]rune(delim))
		}
	}
	return ranges
}

// build aligned cells for all lines; returns per effective-line cells
func (d *Document) buildFullCells(width int) [][]Cell {
	s := d.Settings
	n := d.effCount()
	full := make([][]Cell, n)
	// first pass: base cells expanded tabs (unless align will handle)
	base := make([][]Cell, n)
	for i := 0; i < n; i++ {
		dl := d.effLine(i)
		if dl == nil {
			continue
		}
		cells := parseLineCells(dl.Raw, s)
		base[i] = cells
	}
	if s.Converter == "align" {
		// compute widths per column, using text after removing escapes but before tab expansion?
		// Expand tabs per line first for width calc with placeholder? Use tab expansion.
		expanded := make([][]Cell, n)
		for i := range base {
			expanded[i] = expandTabs(base[i], s.TabWidth)
		}
		// compute field ranges per line
		maxCols := 0
		rangesPerLine := make([][]fieldRange, n)
		for i, cells := range expanded {
			r := splitFieldsRange(cells, s.ColumnDelimiter)
			rangesPerLine[i] = r
			if len(r) > maxCols {
				maxCols = len(r)
			}
		}
		widths := make([]int, maxCols)
		for i, cells := range expanded {
			for ci, r := range rangesPerLine[i] {
				w := 0
				for _, c := range cells[r.start:r.end] {
					w += c.Width
				}
				if w > widths[ci] {
					widths[ci] = w
				}
			}
		}
		delimCells := []Cell{}
		for _, r := range stringToRunes(s.ColumnDelimiter) {
			delimCells = append(delimCells, Cell{R: r, Width: runeDisplayWidth(r)})
		}
		for i, cells := range expanded {
			if len(cells) == 0 {
				full[i] = cells
				continue
			}
			var out []Cell
			ranges := rangesPerLine[i]
			for ci, r := range ranges {
				fieldCells := cells[r.start:r.end]
				out = append(out, fieldCells...)
				if ci < len(ranges)-1 {
					// pad to width
					w := 0
					for _, c := range fieldCells { w += c.Width }
					// right align column?
					pad := widths[ci] - w
					if s.RightAlignColumn {
						for k := 0; k < pad; k++ { /* insert padding before? handled below */ }
						// Build right-aligned: we already appended; need rework
						// Simplify: if right align, padding inserted before field
						if pad > 0 {
							// rebuild: remove field, add pad, add field
							out = out[:len(out)-len(fieldCells)]
							for k := 0; k < pad; k++ { out = append(out, Cell{R: ' ', Width: 1}) }
							out = append(out, fieldCells...)
						}
					} else {
						for k := 0; k < pad; k++ { out = append(out, Cell{R: ' ', Width: 1}) }
					}
					out = append(out, delimCells...)
				}
			}
			full[i] = out
		}
		return full
	}
	for i := range base {
		full[i] = expandTabs(base[i], s.TabWidth)
	}
	return full
}

func (d *Document) cacheVis(width int) {
	if width <= 0 {
		width = 80
	}
	key := d.cacheKeyFor(width)
	if d.cacheKey == key && d.visLines != nil {
		return
	}
	d.cacheKey = key
	full := d.buildFullCells(width)
	// Determine prefix width for wrapping: line number width if enabled
	prefixW := d.lineNumWidth()
	avail := width - prefixW
	if d.Settings.VerticalHeader > 0 && d.X > 0 {
		// vertical header occupies part, but wrap width originally based on full width minus prefix
	}
	if avail < 1 {
		avail = 1
	}
	var vis []*VisLine
	for i, cells := range full {
		if !d.Settings.WrapMode {
			vis = append(vis, &VisLine{DocIdx: i, Cells: cells, Text: cellsText(cells)})
			continue
		}
		if len(cells) == 0 {
			vis = append(vis, &VisLine{DocIdx: i, Cells: nil, Text: ""})
			continue
		}
		// chunk by display width
		start := 0
		for start < len(cells) {
			w := 0
			end := start
			for end < len(cells) {
				cw := cells[end].Width
				if cw == 0 { cw = 1 }
				if w+cw > avail && end > start {
					break
				}
				w += cw
				end++
			}
			if end == start { end = start + 1 }
			chunk := cells[start:end]
			vis = append(vis, &VisLine{DocIdx: i, Offset: start, Cells: chunk, Text: cellsText(chunk)})
			start = end
		}
	}
	d.visLines = vis
	d.fullCellsCache = full
}

func (d *Document) cacheKeyFor(width int) string {
	s := d.Settings
	return fmt.Sprintf("%d|%d|%v|%v|%v|%s|%s|%v|%v|%v|%d|%d|%v|%d|%q|%v", width, len(d.Lines), s.WrapMode, s.LineNumMode, s.Plain, s.Converter, s.ColumnDelimiter, s.ColumnMode, s.ColumnRainbow, s.AlternateRows, s.TabWidth, s.SkipLines, s.MultiColors, s.Header, strings.Join(s.MultiColors, ","), d.X)
}

func (d *Document) lineNumWidth() int {
	if !d.Settings.LineNumMode {
		return 0
	}
	// width = digits of total raw lines? Original: digits of ??? total (12345 ->5) +1 space
	total := len(d.Lines)
	digits := len(fmt.Sprintf("%d", total))
	if total == 0 { digits = 1 }
	return digits + 1
}

// visual row helpers
func (d *Document) bodyStartIdx() int {
	// effective index of first body line = header (clamped)
	h := d.Settings.Header
	if h < 0 { h = 0 }
	if h > d.effCount() { h = d.effCount() }
	return h
}

// find vis index for a doc eff index (first chunk)
func (d *Document) visIndexForDoc(docIdx int) int {
	for i, v := range d.visLines {
		if v.DocIdx >= docIdx {
			return i
		}
	}
	return len(d.visLines)
}
func (d *Document) docIdxForVis(visIdx int) int {
	if visIdx < 0 {
		return visIdx // negative virtual lines: doc idx = visIdx (since header-excluded? caller adjusts)
	}
	if visIdx >= len(d.visLines) {
		if len(d.visLines) == 0 { return visIdx }
		return d.visLines[len(d.visLines)-1].DocIdx
	}
	return d.visLines[visIdx].DocIdx
}

// section delimiter regexp
func (d *Document) sectionRegexp() *regexp.Regexp {
	if d.Settings.SectionDelimiter == "" {
		return nil
	}
	re, err := regexp.Compile(d.Settings.SectionDelimiter)
	if err != nil {
		return nil
	}
	return re
}
func (d *Document) isSectionLine(effIdx int) bool {
	re := d.sectionRegexp()
	if re == nil { return false }
	dl := d.effLine(effIdx)
	if dl == nil { return false }
	return re.MatchString(dl.Raw)
}
func (d *Document) sectionStartFor(effIdx int) int {
	re := d.sectionRegexp()
	if re == nil { return -1 }
	start := -1
	for i := 0; i <= effIdx && i < d.effCount(); i++ {
		dl := d.effLine(i)
		if dl != nil && re.MatchString(dl.Raw) {
			start = i
		}
	}
	return start
}
func (d *Document) nextSection(curEff int) (int, bool) {
	re := d.sectionRegexp()
	if re == nil { return 0, false }
	for i := curEff + 1; i < d.effCount(); i++ {
		if d.effLine(i) != nil && re.MatchString(d.effLine(i).Raw) {
			return i, true
		}
	}
	return 0, false
}
func (d *Document) prevSection(curEff int) (int, bool) {
	re := d.sectionRegexp()
	if re == nil { return 0, false }
	for i := curEff - 1; i >= 0; i-- {
		if d.effLine(i) != nil && re.MatchString(d.effLine(i).Raw) {
			return i, true
		}
	}
	return 0, false
}
func (d *Document) lastSection() (int, bool) {
	re := d.sectionRegexp()
	if re == nil { return 0, false }
	for i := d.effCount() - 1; i >= 0; i-- {
		if d.effLine(i) != nil && re.MatchString(d.effLine(i).Raw) {
			return i, true
		}
	}
	return 0, false
}

// search matching
func makeSearcher(word string, caseSensitive, smartCase, regexpSearch bool) (func(string) bool, []func(string) [][2]int) {
	// returns matcher
	return nil, nil
}

type Searcher struct {
	Word string
	CaseSensitive bool
	SmartCase bool
	Regexp bool
	NonMatch bool
	re *regexp.Regexp
	reErr bool
}

func (s *Searcher) effectiveCase() bool {
	if s.CaseSensitive { return true }
	if s.SmartCase && strings.IndexFunc(s.Word, func(r rune) bool { return r >= 'A' && r <= 'Z' }) >= 0 { return true }
	return false
}
func (s *Searcher) compile() {
	if s.Word == "" { s.re = nil; return }
	if s.Regexp {
		pat := s.Word
		if !s.effectiveCase() { pat = "(?i)" + pat }
		re, err := regexp.Compile(pat)
		if err != nil { s.re = nil; s.reErr = true; return }
		s.re = re
		s.reErr = false
	} else {
		s.re = nil
	}
}
func (s *Searcher) match(text string) bool {
	if s.Word == "" { return false }
	m := false
	if s.Regexp {
		if s.re == nil { return false }
		m = s.re.MatchString(text)
	} else {
		if s.effectiveCase() {
			m = strings.Contains(text, s.Word)
		} else {
			m = strings.Contains(strings.ToLower(text), strings.ToLower(s.Word))
		}
	}
	if s.NonMatch { return !m }
	return m
}
func (s *Searcher) findRanges(text string) [][2]int {
	if s.Word == "" || s.NonMatch { return nil }
	if s.Regexp {
		if s.re == nil { return nil }
		locs := s.re.FindAllStringIndex(text, -1)
		var out [][2]int
		for _, l := range locs { out = append(out, [2]int{l[0], l[1]}) }
		return out
	}
	var out [][2]int
	hay := text
	needle := s.Word
	if !s.effectiveCase() {
		hay = strings.ToLower(text)
		needle = strings.ToLower(s.Word)
	}
	start := 0
	for {
		idx := strings.Index(hay[start:], needle)
		if idx < 0 { break }
		sPos := start + idx
		out = append(out, [2]int{sPos, sPos + len(needle)})
		start = sPos + len(needle)
		if len(needle) == 0 { break }
	}
	return out
}

// tcell style helper used elsewhere
var _ = tcell.StyleDefault
