{"command":"cat > render.go <<'EOF'
package main

import (
	"fmt"
	"strings"

	"github.com/gdamore/tcell/v2"
)

type layoutInfo struct {
	W, H          int
	ContentRows   int // rows above status/prompt
	HeaderRows    int // ruler+fixed header+section header rows
	BodyRows      int
	RulerRows     int
	FixedHdrVis   []*VisLine // regular header vis lines
	SectionHdrVis []*VisLine
	SectionStart  int
	BodyVis       []*VisLine // vis lines with DocIdx >= header start
	LineNumW      int
	ContentX      int // x offset due sidebar
	ContentW      int
}

func (a *App) layout(doc *Document) layoutInfo {
	w, h := a.screen.Size()
	contentW := w
	contentX := 0
	if a.sidebar != 0 {
		contentX = 16
		contentW = w - 16
		if contentW < 1 { contentW = 1 }
	}
	doc.cacheVis(contentW)
	li := layoutInfo{W: w, H: h, ContentX: contentX, ContentW: contentW}
	// content rows
	if doc.Settings.StatusLine || a.inputMode != "" {
		li.ContentRows = h - 1
	} else {
		li.ContentRows = h
	}
	if li.ContentRows < 0 { li.ContentRows = 0 }
	if doc.Settings.Ruler != 0 {
		li.RulerRows = 2
	}
	header := doc.Settings.Header
	if header < 0 { header = 0 }
	// collect fixed header vis and body vis
	for _, v := range doc.visLines {
		if v.DocIdx < header {
			li.FixedHdrVis = append(li.FixedHdrVis, v)
		} else {
			li.BodyVis = append(li.BodyVis, v)
		}
	}
	li.SectionStart = -1
	if doc.Settings.SectionHeader {
		// determine top doc idx
		topDoc := doc.topDocIdx(li)
		if sec := doc.sectionStartFor(topDoc); sec >= 0 {
			li.SectionStart = sec
			num := doc.Settings.SectionHeaderNum
			if num < 1 { num = 1 }
			for _, v := range doc.visLines {
				if v.DocIdx >= sec && v.DocIdx < sec+num {
					li.SectionHdrVis = append(li.SectionHdrVis, v)
				}
			}
		}
	}
	li.HeaderRows = li.RulerRows + len(li.FixedHdrVis) + len(li.SectionHdrVis)
	li.BodyRows = li.ContentRows - li.HeaderRows
	if li.BodyRows < 0 { li.BodyRows = 0 }
	li.LineNumW = doc.lineNumWidth()
	return li
}

func (doc *Document) topDocIdx(li layoutInfo) int {
	t := doc.Top
	if t < 0 {
		return doc.bodyStartIdx() + t
	}
	if t < len(li.BodyVis) {
		return li.BodyVis[t].DocIdx
	}
	if len(li.BodyVis) > 0 {
		return li.BodyVis[len(li.BodyVis)-1].DocIdx
	}
	return doc.bodyStartIdx() + t
}
func (doc *Document) statusLineNum(li layoutInfo) int {
	return doc.Settings.SkipLines + doc.topDocIdx(li) + 1
}
func (doc *Document) maxTop(li layoutInfo) int {
	return len(li.BodyVis) - (li.BodyRows - 1)
}

// full line cells for doc idx (from cache)
func (doc *Document) fullCells(docIdx int) []Cell {
	if docIdx < 0 || docIdx >= len(doc.fullCellsCache) {
		return nil
	}
	return doc.fullCellsCache[docIdx]
}

func (a *App) draw() {
	if a.screen == nil {
		return
	}
	a.screen.Clear()
	doc := a.currentDoc()
	if doc == nil {
		a.screen.Show()
		return
	}
	li := a.layout(doc)
	w, h := li.W, li.H
	_ = h
	// draw sidebar
	if a.sidebar != 0 {
		a.drawSidebar(doc, li)
	}
	row := 0
	// ruler
	if li.RulerRows > 0 {
		a.drawRuler(doc, li, row)
		row += 2
	}
	// fixed header
	for _, v := range li.FixedHdrVis {
		if row >= li.ContentRows { break }
		a.drawLine(doc, li, v, row, true, false)
		row++
	}
	// section header
	for _, v := range li.SectionHdrVis {
		if row >= li.ContentRows { break }
		a.drawLine(doc, li, v, row, false, true)
		row++
	}
	// body
	// Determine current section for hide-other
	hideStart, hideEnd := -1, -1
	if doc.Settings.HideOtherSection && doc.Settings.SectionDelimiter != "" {
		topDoc := doc.topDocIdx(li)
		sec := doc.sectionStartFor(topDoc)
		if sec < 0 {
			sec = 0
			// section before first delimiter runs to first delimiter
			hideStart = 0
			if nxt, ok := doc.nextSection(-1); ok {
				hideEnd = nxt
			} else {
				hideEnd = doc.effCount()
			}
			_ = sec
		} else {
			hideStart = sec
			hideEnd = doc.effCount()
			if nxt, ok := doc.nextSection(sec); ok {
				hideEnd = nxt
			}
		}
	}
	for br := 0; br < li.BodyRows; br++ {
		screenRow := row + br
		if screenRow >= li.ContentRows { break }
		visIdx := doc.Top + br
		if visIdx < 0 || visIdx >= len(li.BodyVis) {
			a.drawTilde(doc, li, screenRow)
			continue
		}
		v := li.BodyVis[visIdx]
		if doc.Settings.HideOtherSection && doc.Settings.SectionDelimiter != "" {
			if v.DocIdx < hideStart || v.DocIdx >= hideEnd {
				// blank row
				continue
			}
		}
		// skip section header lines in body when they are shown as section header and vis is at/near header
		if doc.Settings.SectionHeader && li.SectionStart >= 0 {
			num := doc.Settings.SectionHeaderNum
			if num < 1 { num = 1 }
			// Only skip if the body position is within section header range (vis DocIdx in range)
			// To mimic advancing: we simply render; skipping is handled by movement logic.
			_ = num
		}
		isJump := false
		if jt := jumpTargetOffset(doc, li); jt >= 0 && br == jt {
			isJump = true
		}
		a.drawLine(doc, li, v, screenRow, false, false)
		if isJump {
			a.applyJumpStyle(doc, li, v, screenRow)
		}
	}
	// status / prompt
	if doc.Settings.StatusLine || a.inputMode != "" {
		a.drawStatus(doc, li)
	}
	a.screen.Show()
}

func jumpTargetOffset(doc *Document, li layoutInfo) int {
	// returns body row offset or -1
	jt := doc.Settings.JumpTarget
	if jt == "" {
		return -1
	}
	// parse like setJumpTarget but don't validate beyond
	return parseJumpTargetValue(jt, li.BodyRows)
}

func parseJumpTargetValue(v string, bodyRows int) int {
	v = strings.TrimSpace(v)
	if v == "" || v == "section" {
		return -1
	}
	if strings.HasSuffix(v, "%") {
		numStr := strings.TrimSuffix(v, "%")
		var f float64
		if _, err := fmt.Sscan(numStr, &f); err != nil { return -1 }
		return int(f / 100.0 * float64(bodyRows))
	}
	if strings.HasPrefix(v, ".") {
		var f float64
		if _, err := fmt.Sscan(v, &f); err != nil { return -1 }
		return int(f * float64(bodyRows))
	}
	var n int
	if _, err := fmt.Sscan(v, &n); err != nil { return -1 }
	return n
}

func (a *App) drawTilde(doc *Document, li layoutInfo, row int) {
	style := tcell.StyleDefault.Foreground(tcell.PaletteColor(8))
	x := li.ContentX + li.LineNumW
	if x < li.W {
		a.screen.SetContent(x, row, '~', nil, style)
	}
}

func (a *App) drawRuler(doc *Document, li layoutInfo, startRow int) {
	style := styleFromSpec(doc.Settings.StyleRuler, tcell.StyleDefault)
	// two rows
	for r := 0; r < 2; r++ {
		row := startRow + r
		for x := 0; x < li.ContentW; x++ {
			var ch rune
			pos := x + doc.X // absolute if ruler==2? relative ruler ignores X? original relative vs absolute difference on scroll
			if doc.Settings.Ruler == 2 {
				// absolute: numbers based on pos
			} else {
				pos = x
			}
			if r == 0 {
				if (pos+1)%10 == 0 {
					// digit of tens? original first row: spaces then "1" at col 9 (for 10), "2" at 19...
					num := (pos + 1) / 10
					ch = rune('0' + (num % 10))
					if num == 0 { ch = ' ' }
				} else {
					ch = ' '
				}
			} else {
				ch = rune('0' + (pos % 10))
			}
			a.screen.SetContent(li.ContentX+x, row, ch, nil, style)
		}
	}
}

// drawLine renders a VisLine at screen row
func (a *App) drawLine(doc *Document, li layoutInfo, v *VisLine, row int, isFixedHeader bool, isSectionHeader bool) {
	s := doc.Settings
	baseX := li.ContentX
	// line number
	if s.LineNumMode {
		var numStr string
		if isFixedHeader || isSectionHeader {
			numStr = strings.Repeat(" ", li.LineNumW)
		} else {
			num := v.DocIdx - s.Header + 1
			if s.Header < 0 { num = v.DocIdx + 1 }
			digits := li.LineNumW - 1
			if digits < 1 { digits = 1 }
			numStr = fmt.Sprintf("%*d ", digits, num)
		}
		style := styleFromSpec(s.StyleLineNumber, tcell.StyleDefault)
		// For header lines with line numbers, original shows blank field not styled? keep style
		for i, ch := range numStr {
			a.screen.SetContent(baseX+i, row, ch, nil, style)
		}
	}
	contentX := baseX + li.LineNumW
	availW := li.ContentW - li.LineNumW
	if availW < 0 { availW = 0 }

	// get cells sliced by X / wrap / vertical header
	cells := v.Cells
	// For unwrapped, apply horizontal scroll
	var displayCells []Cell
	if s.WrapMode {
		displayCells = cells
	} else {
		if s.VerticalHeader > 0 {
			n := s.VerticalHeader
			if n > len(cells) {
				// pad
				padded := make([]Cell, n)
				copy(padded, cells)
				for i := len(cells); i < n; i++ { padded[i] = Cell{R: ' ', Width: 1} }
				fixed := padded[:n]
				var rest []Cell
				if doc.X > 0 {
					start := doc.X + n
					if start < len(cells) { rest = cells[start:] }
				} else {
					// rest is beyond fixed in original line (none if padded)
					if len(cells) > n { rest = cells[n:] }
				}
				displayCells = append(append([]Cell{}, fixed...), rest...)
			} else {
				fixed := cells[:n]
				var rest []Cell
				start := doc.X + n
				if doc.X == 0 {
					rest = cells[n:]
					displayCells = cells
					_ = fixed
					_ = rest
				} else {
					if start < len(cells) { rest = cells[start:] }
					displayCells = append(append([]Cell{}, fixed...), rest...)
				}
			}
		} else if doc.X > 0 {
			if doc.X < len(cells) {
				displayCells = cells[doc.X:]
			} else {
				displayCells = nil
			}
		} else {
			displayCells = cells
		}
	}

	// Determine if this is a section line
	isSection := false
	if !isFixedHeader && doc.isSectionLine(v.DocIdx) {
		isSection = true
	}
	// full line cells for highlights
	fullCells := doc.fullCells(v.DocIdx)
	// column ranges on full cells
	var colRanges []fieldRange
	if (s.ColumnMode || s.ColumnRainbow) && fullCells != nil {
		colRanges = splitFieldsRange(fullCells, s.ColumnDelimiter)
	}
	searcher := a.searcherFor(doc)
	var searchRanges [][2]int
	if searcher != nil && searcher.Word != "" {
		text := cellsText(fullCells)
		// findRanges uses rune? it returns byte indices; convert to rune indices by using rune slice
		searchRanges = byteRangesToRuneRanges(text, searcher.findRanges(text))
	}
	var multiRanges [][][2]int
	var multiPatterns []string
	if len(s.MultiColors) > 0 {
		for _, pat := range s.MultiColors {
			re := compilePattern(pat, searcher)
			var rr [][2]int
			if re != nil {
				text := cellsText(fullCells)
				locs := re.FindAllStringIndex(text, -1)
				for _, l := range locs { rr = append(rr, [2]int{l[0], l[1]}) }
				rr = byteRangesToRuneRanges(text, rr)
			}
			multiRanges = append(multiRanges, rr)
			multiPatterns = append(multiPatterns, pat)
		}
	}

	// Alternate rows: based on doc line index parity (second line shaded)
	alternate := s.AlternateRows && (v.DocIdx%2 == 1)

	// Iterate display cells with their original full-line index
	// For wrap mode, v.Offset is start index in full cells
	// For nowrap with vertical header etc., mapping complicated; approximate by display position index when X==0, else offset+X
	xpos := 0
	for idx, c := range displayCells {
		if xpos >= availW { break }
		// compute full index
		fullIdx := idx
		if s.WrapMode {
			fullIdx = v.Offset + idx
		} else {
			if s.VerticalHeader > 0 && doc.X > 0 {
				if idx < s.VerticalHeader {
					fullIdx = idx
				} else {
					fullIdx = doc.X + s.VerticalHeader + (idx - s.VerticalHeader)
				}
			} else if doc.X > 0 {
				fullIdx = doc.X + idx
			}
		}
		style := c.Style
		// base body
		if alternate {
			style = styleFromSpec(s.StyleAlternate, style)
		}
		if isFixedHeader || isSectionHeader {
			style = styleFromSpec(s.StyleHeader, style)
			if isSectionHeader {
				style = styleFromSpec(s.StyleSectionLine, style)
			}
		} else if isSection {
			style = styleFromSpec(s.StyleSectionLine, style)
		}
		// multi color (before search/column so search can override?)
		for mi, rr := range multiRanges {
			_ = multiPatterns
			if inRanges(fullIdx, rr) {
				if mi < len(s.MultiColorStyles) {
					style = styleFromSpec(s.MultiColorStyles[mi], style)
				}
			}
		}
		// column rainbow / highlight
		if (s.ColumnMode || s.ColumnRainbow) && colRanges != nil && len(colRanges) > 1 {
			for ci, r := range colRanges {
				if fullIdx >= r.start && fullIdx < r.end {
					if s.ColumnRainbow && ci < len(s.ColumnRainbowStyles) {
						style = styleFromSpec(s.ColumnRainbowStyles[ci], style)
					}
					if s.ColumnMode && ci == doc.ColumnCursor {
						style = styleFromSpec(s.StyleColumn, style)
					}
					break
				}
			}
		}
		// search highlight
		if searchRanges != nil && inRanges(fullIdx, searchRanges) {
			style = styleFromSpec(s.StyleSearch, style)
		}
		// mark
		if a.isMarked(doc, v.DocIdx) && fullIdx < s.MarkStyleWidth {
			style = styleFromSpec(s.StyleMark, style)
		}
		// vertical header border
		if s.VerticalHeader > 0 {
			if idx == s.VerticalHeader-1 {
				style = styleFromSpec(s.StyleVerticalBorder, style)
			} else if idx < s.VerticalHeader-1 {
				style = styleFromSpec(s.StyleVerticalHdr, style)
			}
		}
		// draw
		screenX := contentX + xpos
		if c.Width == 2 {
			// wide rune
			a.screen.SetContent(screenX, row, c.R, nil, style)
			if screenX+1 < baseX+li.ContentW {
				a.screen.SetContent(screenX+1, row, ' ', nil, style)
			}
			xpos += 2
		} else {
			a.screen.SetContent(screenX, row, c.R, nil, style)
			xpos += c.Width
			if c.Width == 0 { xpos += 1 }
		}
	}
	// If vertical header beyond line length, draw border space
	if s.VerticalHeader > 0 && !s.WrapMode {
		// handled via padded cells above when len<n; for wrap/short also:
		if len(displayCells) < s.VerticalHeader {
			bx := contentX + s.VerticalHeader - 1
			if bx < baseX+li.ContentW {
				style := styleFromSpec(s.StyleVerticalBorder, tcell.StyleDefault)
				a.screen.SetContent(bx, row, ' ', nil, style)
			}
		}
	}
	if s.VerticalHeader > 0 && s.WrapMode {
		// first chunk: border at N-1 if within avail
		if v.Offset == 0 {
			bx := contentX + s.VerticalHeader - 1
			if bx < baseX+li.ContentW && s.VerticalHeader-1 < len(displayCells)+ (s.VerticalHeader-len(displayCells)) {
				// only if line shorter than N, draw border space; if longer, style already applied to that cell
				if len(v.Cells) < s.VerticalHeader {
					style := styleFromSpec(s.StyleVerticalBorder, tcell.StyleDefault)
					a.screen.SetContent(bx, row, ' ', nil, style)
				}
			}
		}
	}
}

func (a *App) applyJumpStyle(doc *Document, li layoutInfo, v *VisLine, row int) {
	// underline the whole line at jump target row (content part)
	styleSpec := doc.Settings.StyleJumpTarget
	contentX := li.ContentX + li.LineNumW
	for x := contentX; x < li.ContentX+li.ContentW; x++ {
		// preserve existing rune but add underline - need to read screen content
		mainc, comb, style, _ := a.screen.GetContent(x, row)
		if mainc == 0 { mainc = ' ' }
		style = styleFromSpec(styleSpec, style)
		a.screen.SetContent(x, row, mainc, comb, style)
		// stop at end of line text? Original underlines whole line text only, not to screen edge.
		// We approximate: if rest blank beyond line, break after we passed line length +? We'll break when remaining are spaces and we already passed text length?
		_ = v
		// To match original, only underline visible text cells. Continue scanning but if we detect trailing spaces beyond text, they were set with default; original capture: line "4" single char underlined only.
		// Break logic: if x-contentX >= len(v.Cells) and mainc==' ' { // we have already underlined spaces? undo by resetting? simpler break before
		// }
		if x-contentX >= len(v.Cells) {
			// undo this cell
			a.screen.SetContent(x, row, mainc, comb, styleFromSpec(StyleSpec{}, style)) // no-op
			break
		}
	}
}

func inRanges(idx int, ranges [][2]int) bool {
	for _, r := range ranges {
		if idx >= r[0] && idx < r[1] { return true }
	}
	return false
}

func byteRangesToRuneRanges(text string, ranges [][2]int) [][2]int {
	if ranges == nil { return nil }
	// convert byte index to rune index mapping
	byteToRune := map[int]int{}
	runeIdx := 0
	for byteIdx := range text {
		byteToRune[byteIdx] = runeIdx
		runeIdx++
	}
	byteToRune[len(text)] = runeIdx
	var out [][2]int
	for _, r := range ranges {
		s, ok1 := byteToRune[r[0]]
		e, ok2 := byteToRune[r[1]]
		if !ok1 || !ok2 { continue }
		out = append(out, [2]int{s, e})
	}
	return out
}

func (a *App) isMarked(doc *Document, effIdx int) bool {
	rawIdx := effIdx + doc.Settings.SkipLines
	return doc.Marks[rawIdx]
}

func (a *App) drawStatus(doc *Document, li layoutInfo) {
	w, h := li.W, li.H
	row := h - 1
	if row < 0 { return }
	li2 := li
	right := ""
	totalStr := ""
	if doc.IsLog {
		totalStr = fmt.Sprintf("%d...", len(doc.Lines))
	} else {
		totalStr = fmt.Sprintf("%d", len(doc.Lines))
	}
	statusNum := doc.statusLineNum(li2)
	right = fmt.Sprintf("(%d/%s)", statusNum, totalStr)

	var left string
	var leftStyle tcell.Style
	isInput := a.inputMode != ""
	if isInput {
		left = a.promptText(doc)
		leftStyle = tcell.StyleDefault
	} else {
		left = a.statusLeft(doc)
		leftStyle = tcell.StyleDefault.Reverse(true)
		if doc.IsFilter {
			leftStyle = leftStyle.Foreground(tcell.PaletteColor(9))
		}
		if doc.Settings.PromptInvert {
			// invert whole? keep reverse
		}
	}
	// truncate left to fit right
	leftRunes := []rune(left)
	rightRunes := []rune(right)
	maxLeft := w - len(rightRunes)
	if maxLeft < 0 { maxLeft = 0 }
	if len(leftRunes) > maxLeft {
		leftRunes = leftRunes[:maxLeft]
	}
	// clear row
	for x := 0; x < w; x++ {
		a.screen.SetContent(x, row, ' ', nil, tcell.StyleDefault)
	}
	for i, r := range leftRunes {
		a.screen.SetContent(i, row, r, nil, leftStyle)
	}
	for i, r := range rightRunes {
		x := w - len(rightRunes) + i
		a.screen.SetContent(x, row, r, nil, tcell.StyleDefault)
	}
	if isInput {
		cursorX := len(leftRunes)
		if cursorX >= w { cursorX = w - 1 }
		a.screen.ShowCursor(cursorX, row)
	} else {
		a.screen.HideCursor()
	}
}

func (a *App) statusLeft(doc *Document) string {
	var prefix string
	if doc.FollowMode {
		prefix = "(Follow Mode)"
	} else if doc.FollowAll {
		prefix = "(Follow All)"
	} else if doc.FollowSection {
		prefix = "(Follow Section)"
	} else if doc.WatchMode {
		prefix = "(Watch)"
	}
	name := doc.Name
	if doc.Caption != "" {
		name = doc.Caption
	}
	// index prefix if multiple docs and not special doc
	if !doc.IsHelp && !doc.IsLog && len(a.docs) > 1 {
		idx := a.indexOfDoc(doc)
		if idx >= 0 {
			name = fmt.Sprintf("[%d]%s", idx, name)
		}
	}
	left := prefix + name + ":"
	if a.message != "" {
		left += a.message
	}
	return left
}

func (a *App) indexOfDoc(doc *Document) int {
	for i, d := range a.docs {
		if d == doc { return i }
	}
	return -1
}

func (a *App) promptText(doc *Document) string {
	switch a.inputMode {
	case "search":
		return a.searchPromptPrefix("/") + a.input
	case "backsearch":
		return a.searchPromptPrefix("?") + a.input
	case "filter":
		return a.searchPromptPrefix("&") + a.input
	case "markpattern":
		return "*" + a.input
	case "goto":
		return "Goto line:" + a.input
	case "header":
		return "Header length:" + a.input
	case "tabwidth":
		return "TAB width:" + a.input
	case "skiplines":
		return "Skip lines:" + a.input
	case "delimiter":
		return "Delimiter:" + a.input
	case "multicolor":
		return "Multi color:" + a.input
	case "jumptarget":
		return "Jump target line:" + a.input
	case "verticalheader":
		return "Vertical header length:" + a.input
	case "headercolumn":
		return "Header column:" + a.input
	case "viewmode":
		return "Mode:" + a.input
	case "convert":
		return "Convert:" + a.input
	case "sectiondelimiter":
		return "Section delimiter:" + a.input
	case "sectionstart":
		return "Section start:" + a.input
	case "sectionnum":
		return "Section Num:" + a.input
	case "watchinterval":
		return "Watch interval:" + a.input
	case "savefile":
		return "(Save)file:" + a.input
	case "marknumber":
		return "Mark number:" + a.input
	case "writeandquit":
		return "WriteAndQuit Before:After:" + a.input
	default:
		return a.input
	}
}

func (a *App) searchPromptPrefix(kind string) string {
	s := a.search
	var b strings.Builder
	if s != nil {
		if s.Regexp { b.WriteString("(R)") }
		// filter mode doesn't show incsearch
		if a.inputMode != "filter" && s.Incsearch { b.WriteString("(I)") }
		if s.CaseSensitive {
			b.WriteString("(Aa)")
		} else if s.SmartCase {
			b.WriteString("(S)")
		}
	}
	b.WriteString(kind)
	if s != nil && s.NonMatch {
		b.WriteString("!")
	}
	return b.String()
}

func (a *App) drawSidebar(doc *Document, li layoutInfo) {
	w := 16
	if li.W < w { w = li.W }
	// title
	var title string
	switch a.sidebar {
	case 1: title = "Files"
	case 2: title = "Marks"
	case 3: title = "Help"
	}
	// center title: original "   Files" (3 spaces +)
	header := fmt.Sprintf("   %s", title)
	styleTitle := tcell.StyleDefault.Bold(true)
	// draw rows up to ContentRows
	for r := 0; r < li.ContentRows; r++ {
		// clear sidebar area
		for x := 0; x < w; x++ {
			a.screen.SetContent(x, r, ' ', nil, tcell.StyleDefault)
		}
	}
	for i, ch := range header {
		if i < w { a.screen.SetContent(i, 0, ch, nil, styleTitle) }
	}
	// separator style? Original has a vertical gray bar at column 15? capture had grey space at col15 in marks prompt.
	// Draw entries
	row := 1
	switch a.sidebar {
	case 1:
		for i, d := range a.docs {
			if row >= li.ContentRows { break }
			name := d.Name
			if d.Caption != "" { name = d.Caption }
			text := fmt.Sprintf(" %d %s", i, name)
			runes := []rune(text)
			if len(runes) > w { runes = runes[:w] }
			st := tcell.StyleDefault
			if i == a.cur { st = st.Reverse(true) }
			for x, ch := range runes {
				a.screen.SetContent(x, row, ch, nil, st)
			}
			row++
		}
	case 2:
		// marks list: entries " <num> <line> <text>" ?
		// Build sorted marks
		marks := sortedMarks(doc)
		for i, m := range marks {
			if row >= li.ContentRows { break }
			// format similar to original capture: " 0 0 1" ??? approximate
			lineText := ""
			if m >= 0 && m < len(doc.RawLines) { lineText = doc.RawLines[m] }
			text := fmt.Sprintf(" %d %d %s", i, m+1, lineText)
			runes := []rune(text)
			if len(runes) > w { runes = runes[:w] }
			for x, ch := range runes {
				a.screen.SetContent(x, row, ch, nil, tcell.StyleDefault)
			}
			row++
		}
	case 3:
		// help sidebar entries: keys then desc on next line
		entries := sidebarHelpEntries(a.cfg.cfg.KeyBind)
		// scroll by sidebarTop
		for idx := a.sidebarTop; idx < len(entries) && row < li.ContentRows; idx++ {
			text := entries[idx]
			runes := []rune(text)
			if len(runes) > w { runes = runes[:w] }
			for x, ch := range runes {
				a.screen.SetContent(x, row, ch, nil, tcell.StyleDefault)
			}
			row++
		}
	}
	// vertical border at x=15?
	for r := 0; r < li.ContentRows; r++ {
		st := tcell.StyleDefault.Background(tcell.PaletteColor(8))
		// original marks sidebar showed grey at last column; only when marks sidebar from prompt? Use subtle
		_ = st
		// don't draw to keep plain text clean
	}
}

func sidebarHelpEntries(kb map[string][]string) []string {
	var out []string
	for _, cat := range helpCategories {
		for _, act := range cat.actions {
			keys := kb[act.action]
			var parts []string
			for _, k := range keys { parts = append(parts, displayKey(k)) }
			out = append(out, "["+strings.Join(parts, ", ")+"]")
			out = append(out, "  "+act.desc)
		}
	}
	return out
}

func sortedMarks(doc *Document) []int {
	var out []int
	for k := range doc.Marks { out = append(out, k) }
	// sort
	for i := 0; i < len(out); i++ {
		for j := i + 1; j < len(out); j++ {
			if out[j] < out[i] { out[i], out[j] = out[j], out[i] }
		}
	}
	return out
}
