func sidebarHelpEntries(kb map[string][]string) []string {
	var out []string
	for _, cat := range helpCategories {
		for _, act := range cat.actions {
			keys := kb[act.action]
			var parts []string
			for _, k := range keys { parts = append(parts, displayKey(k)) }
			out = append(out, "["+strings.Join(parts, ", ")+"]")
			out = append(out, "  "+act.desc)
		}
	}
	return out
}

func sortedMarks(doc *Document) []int {
	var out []int
	for k := range doc.Marks { out = append(out, k) }
	// sort
	for i := 0; i < len(out); i++ {
		for j := i + 1; j < len(out); j++ {
			if out[j] < out[i] { out[i], out[j] = out[j], out[i] }
		}
	}
	return out
}
