func renderLineText(doc *Document, li layoutInfo, v *VisLine) string {
	// Build plain text of this vis line, respecting wrap/x etc, without styles
	s := doc.Settings
	cells := v.Cells
	var display []Cell
	if s.WrapMode {
		display = cells
	} else {
		if s.VerticalHeader > 0 && doc.X > 0 {
			n := s.VerticalHeader
			var fixed []Cell
			if n <= len(cells) { fixed = cells[:n] }
			var rest []Cell
			if doc.X+n < len(cells) { rest = cells[doc.X+n:] }
			display = append(append([]Cell{}, fixed...), rest...)
		} else if doc.X > 0 {
			if doc.X < len(cells) { display = cells[doc.X:] } else { display = nil }
		} else {
			display = cells
		}
	}
	// line number prefix
	prefix := ""
	if s.LineNumMode {
		if false {
		} else {
			num := v.DocIdx - s.Header + 1
			digits := li.LineNumW - 1
			if digits < 1 { digits = 1 }
