func (a *App) periodic() {
	now := time.Now()
	if now.Sub(a.lastFollowCheck) < 200*time.Millisecond { return }
	a.lastFollowCheck = now
	doc := a.currentDoc()
	if doc == nil { return }
	changed := false
	if doc.FollowMode || doc.FollowAll || doc.WatchMode || (a.flags.watchInterval > 0) || doc.IsLog {
		if doc.FilePath != "" {
			if st, err := os.Stat(doc.FilePath); err == nil {
				if st.ModTime().UnixNano() != doc.lastModUnixNano || st.Size() != doc.lastSize {
					// reload
					a.reloadDoc(doc, true)
					changed = true
					if doc.FollowMode {
