}

// goto line (1-based raw). Returns message
func (a *App) gotoLine(doc *Document, input string) string {
	input = strings.TrimSpace(input)
	if input == "" { return "" }
	li := a.layout(doc)
	total := len(doc.Lines)
	var target int // 1-based raw line
	if strings.HasSuffix(input, "%") {
		numStr := strings.TrimSuffix(input, "%")
		f, err := strconv.ParseFloat(numStr, 64)
		if err != nil { return "invalid number" }
		target = int(float64(total) * f / 100.0)
		return a.gotoTarget(doc, li, target, fmt.Sprintf("Moved to line %v", formatFloat(f, total)))
	}
	if strings.HasPrefix(input, ".") {
		f, err := strconv.ParseFloat(input, 64)
		if err != nil { return "invalid number" }
		target = int(float64(total) * f)
		return a.gotoTarget(doc, li, target, fmt.Sprintf("Moved to line %v", formatFloat(f*100, total)))
	}
	n, err := strconv.Atoi(input)
	if err != nil {
		// try float like "1.5"? original invalid?
		return "invalid number"
	}
	target = n
	return a.gotoTarget(doc, li, target, fmt.Sprintf("Moved to line %d", target))
}

func formatFloat(pct float64, total int) string {
	// original for 50% and .5 showed "6172.0"
	v := float64(total) * pct / 100.0
	// truncate to int then format as float with .0
	iv := int(v)
	return fmt.Sprintf("%d.0", iv)
}

func (a *App) gotoTarget(doc *Document, li layoutInfo, target int, msg string) string {
	total := len(doc.Lines)
	if target > total { target = total }
	// target 0 -> one before first
	effTarget := target - 1 - doc.Settings.SkipLines // eff index
	// convert to BodyVis index
	if target == 0 {
		doc.Top = -1 - 0 // BodyVis coordinates: -1 relative to first body line
		// our BodyVis starts at header; Top=-1 yields first row tilde then body first
		return msg
	}
	// find vis index
	idx := -1
	for i, v := range li.BodyVis {
		if v.DocIdx >= effTarget {
			idx = i
			break
		}
	}
	if idx < 0 {
		if len(li.BodyVis) > 0 { idx = len(li.BodyVis) - 1 } else { idx = 0 }
	}
	doc.Top = idx
	return msg
}

func (a *App) focusDocIdx(doc *Document, li layoutInfo) int {
	jt := jumpTargetOffset(doc, li)
	visIdx := doc.Top
	if jt > 0 { visIdx += jt }
	if visIdx < 0 { return doc.bodyStartIdx() + visIdx }
	if visIdx < len(li.BodyVis) { return li.BodyVis[visIdx].DocIdx }
	if len(li.BodyVis) > 0 { return li.BodyVis[len(li.BodyVis)-1].DocIdx }
	return 0
}

// search execution
func (a *App) doSearch(doc *Document, s *Searcher, backward bool, fromStart bool) bool {
	if s.Word == "" { return false }
	s.compile()
	if s.reErr {
		a.message = fmt.Sprintf("search:not found:%s", s.Word)
		return false
	}
	li := a.layout(doc)
	var startEff int
	if fromStart {
		startEff = a.inputStartDoc
		// fromStart means inclusive of start
		if backward {
			// search <= start
			for i := startEff; i >= 0; i-- {
				if i < doc.effCount() && s.match(doc.effLineRaw(i)) {
					a.positionToMatch(doc, li, i)
					return true
				}
			}
		} else {
			for i := startEff; i < doc.effCount(); i++ {
				if s.match(doc.effLineRaw(i)) {
					a.positionToMatch(doc, li, i)
					return true
				}
			}
		}
		return false
	}
	focus := a.focusDocIdx(doc, li)
	if backward {
		for i := focus - 1; i >= 0; i-- {
			if s.match(doc.effLineRaw(i)) {
				a.positionToMatch(doc, li, i)
				return true
			}
		}
	} else {
		for i := focus + 1; i < doc.effCount(); i++ {
			if s.match(doc.effLineRaw(i)) {
				a.positionToMatch(doc, li, i)
				return true
			}
		}
	}
	return false
}

func (doc *Document) effLineRaw(effIdx int) string {
	dl := doc.effLine(effIdx)
	if dl == nil { return "" }
	return dl.Raw
}

func (a *App) positionToMatch(doc *Document, li layoutInfo, effIdx int) {
	// find BodyVis index for effIdx
	idx := -1
	for i, v := range li.BodyVis {
		if v.DocIdx >= effIdx { idx = i; break }
	}
	if idx < 0 { return }
	jt := jumpTargetOffset(doc, li)
	if jt < 0 { jt = 0 }
	doc.Top = idx - jt
	if doc.Top < -100000 { doc.Top = idx }
	// If match before header etc, allow Top negative? Original seems to clamp when top at very start? With jt and match at line0, top could go negative; keep as computed but not below -effIdx?
	// Clamp so that we don't go far negative beyond - (header?) : keep min -idx
	if doc.Top < 0 && idx < jt {
		// keep negative as original bottom-like? For small files it allowed negative. Keep.
	}
}

func (a *App) reloadDoc(doc *Document, keepPos bool) {
	if doc.FilePath == "" { return }
	data, err := readFileBytes(doc.FilePath)
	if err != nil { return }
	lines := splitLines(data)
	top := doc.Top
	x := doc.X
	doc.setLines(lines)
	doc.cacheKey = ""
	if st, err := os.Stat(doc.FilePath); err == nil {
		doc.lastSize = st.Size()
		doc.lastModUnixNano = st.ModTime().UnixNano()
	}
	if keepPos {
		doc.Top = top
		doc.X = x
	}
}

func (a *App) logf(format string, args ...interface{}) {
	msg := fmt.Sprintf(format, args...)
	ts := time.Now().Format("2006/01/02 15:04:05")
	a.logLines = append(a.logLines, ts+" "+msg)
	if a.logDoc != nil && a.special != a.logDoc {
		// will be synced when opened / periodically
		a.logDoc.setLines(append([]string{}, a.logLines...))
		a.logDoc.cacheKey = ""
	}
}

func readFileBytes(path string) ([]byte, error) {
	return os.ReadFile(path)
}

var _ = sort.Strings
var _ = utf8.RuneLen
var _ = exec.Command
