func (a *App) gotoLine(doc *Document, input string) string {
	input = strings.TrimSpace(input)
	if input == "" { return "" }
	li := a.layout(doc)
	total := len(doc.Lines)
	var target int // 1-based raw line
	if strings.HasSuffix(input, "%") {
		numStr := strings.TrimSuffix(input, "%")
		f, err := strconv.ParseFloat(numStr, 64)
		if err != nil { return "invalid number" }
		target = int(float64(total) * f / 100.0)
		return a.gotoTarget(doc, li, target, fmt.Sprintf("Moved to line %v", formatFloat(f, total)))
	}
	if strings.HasPrefix(input, ".") {
		f, err := strconv.ParseFloat(input, 64)
		if err != nil { return "invalid number" }
		target = int(float64(total) * f)
		return a.gotoTarget(doc, li, target, fmt.Sprintf("Moved to line %v", formatFloat(f*100, total)))
	}
	n, err := strconv.Atoi(input)
	if err != nil {
		// try float like "1.5"? original invalid?
		return "invalid number"
	}
	target = n
	return a.gotoTarget(doc, li, target, fmt.Sprintf("Moved to line %d", target))
}

func formatFloat(pct float64, total int) string {
	// original for 50% and .5 showed "6172.0"
	v := float64(total) * pct / 100.0
	// truncate to int then format as float with .0
	iv := int(v)
	return fmt.Sprintf("%d.0", iv)
}

func (a *App) gotoTarget(doc *Document, li layoutInfo, target int, msg string) string {
	total := len(doc.Lines)
	if target > total { target = total }
	// target 0 -> one before first
	effTarget := target - 1 - doc.Settings.SkipLines // eff index
	// convert to BodyVis index
	if target == 0 {
		doc.Top = -1 - 0 // BodyVis coordinates: -1 relative to first body line
		// our BodyVis starts at header; Top=-1 yields first row tilde then body first
		return msg
	}
	// find vis index
	idx := -1
	for i, v := range li.BodyVis {
		if v.DocIdx >= effTarget {
			idx = i
			break
		}
	}
	if idx < 0 {
		if len(li.BodyVis) > 0 { idx = len(li.BodyVis) - 1 } else { idx = 0 }
	}
	doc.Top = idx
	return msg
}

