	if jt > 0 { visIdx += jt }
	if visIdx < 0 { return doc.bodyStartIdx() + visIdx }
	if visIdx < len(li.BodyVis) { return li.BodyVis[visIdx].DocIdx }
	if len(li.BodyVis) > 0 { return li.BodyVis[len(li.BodyVis)-1].DocIdx }
	return 0
}

// search execution
func (a *App) doSearch(doc *Document, s *Searcher, backward bool, fromStart bool) bool {
	if s.Word == "" { return false }
	s.compile()
	if s.reErr {
		a.message = fmt.Sprintf("search:not found:%s", s.Word)
		return false
	}
	li := a.layout(doc)
	var startEff int
	if fromStart {
		startEff = a.inputStartDoc
		// fromStart means inclusive of start
		if backward {
			// search <= start
			for i := startEff; i >= 0; i-- {
				if i < doc.effCount() && s.match(doc.effLineRaw(i)) {
					a.positionToMatch(doc, li, i)
					return true
				}
			}
		} else {
			for i := startEff; i < doc.effCount(); i++ {
				if s.match(doc.effLineRaw(i)) {
					a.positionToMatch(doc, li, i)
					return true
				}
			}
		}
		return false
	}
	focus := a.focusDocIdx(doc, li)
	if backward {
		for i := focus - 1; i >= 0; i-- {
			if s.match(doc.effLineRaw(i)) {
				a.positionToMatch(doc, li, i)
				return true
			}
		}
	} else {
		for i := focus + 1; i < doc.effCount(); i++ {
			if s.match(doc.effLineRaw(i)) {
				a.positionToMatch(doc, li, i)
				return true
			}
		}
	}
	return false
}

