func (a *App) handleInputKey(ev *tcell.EventKey) {
	doc := a.currentDoc()
	// Input-specific keybinds (toggles etc.)
	desc := eventKeyDesc(ev)
	// check input actions first for search-like modes
	isSearchLike := a.inputMode == "search" || a.inputMode == "backsearch" || a.inputMode == "filter" || a.inputMode == "markpattern"
	if isSearchLike {
		if action, ok := a.keyMap[desc]; ok {
			switch action {
			case "input_casesensitive":
				s := a.search
				s.CaseSensitive = !s.CaseSensitive
				if s.CaseSensitive { s.SmartCase = false }
				a.afterInputChange(doc)
				return
			case "input_smart_casesensitive":
				s := a.search
				s.SmartCase = !s.SmartCase
				if s.SmartCase { s.CaseSensitive = false }
				a.afterInputChange(doc)
				return
			case "input_regexp_search":
				a.search.Regexp = !a.search.Regexp
				a.afterInputChange(doc)
				return
			case "input_incsearch":
				a.search.Incsearch = !a.search.Incsearch
				a.afterInputChange(doc)
				return
			case "input_non_match":
				a.search.NonMatch = !a.search.NonMatch
				a.afterInputChange(doc)
				return
			}
		}
		// '!' rune is bound as input_non_match; eventKeyDesc gives '!' without mods, keyMap would map to input_non_match
		// handled above because keyMap contains it (action priority). Good.
	}
	// generic input actions: previous/next (Up/Down)
	if action, ok := a.keyMap[desc]; ok && (a.inputMode != "" ) {
		if action == "input_previous" {
			a.inputPrev()
			return
		}
		if action == "input_next" {
			a.inputNext()
			return
		}
		if action == "input_copy" {
			// OSC52: tcell clipboard
			// a.screen.SetClipboard([]byte(a.input)) // not available maybe
			return
		}
		if action == "input_paste" {
			return
		}
	}
	switch ev.Key() {
	case tcell.KeyEnter:
		a.submitInput(doc)
	case tcell.KeyEsc:
		// cancel input; for go_mark close sidebar?
		if a.inputMode == "marknumber" {
			a.sidebar = 0
			for _, d := range a.allDocs() { d.cacheKey = "" }
		}
		a.inputMode = ""
		a.input = ""
		a.search = nil
	case tcell.KeyBS, tcell.KeyBackspace2:
		if len(a.input) > 0 {
			r := []rune(a.input)
			a.input = string(r[:len(r)-1])
			a.afterInputChange(doc)
		}
	case tcell.KeyCtrlC:
		// in input, ctrl+c is copy (keyMap handles) - also could be cancel? Original stays in input.
		return
	case tcell.KeyRune:
		r := ev.Rune()
		// For search-like, '!' handled above; avoid inserting
		if isSearchLike && r == '!' {
			// keyMap would have handled, but if custom binds diff, treat as toggle?
		}
		a.input += string(r)
		a.afterInputChange(doc)
	default:
		// ignore
	}
}

func (a *App) afterInputChange(doc *Document) {
	if doc == nil { return }
	if (a.inputMode == "search" || a.inputMode == "backsearch") && a.search != nil {
		a.search.Word = a.input
		a.search.compile()
		if a.search.Incsearch && a.input != "" {
			backward := a.inputMode == "backsearch"
			// search from start (inclusive)
			found := a.doSearch(doc, a.search, backward, true)
			if !found {
				// stay at start? original incsearch on not found keeps current position (which may have moved on partial)
				// If no match, keep position as is
			}
		} else if a.search.Incsearch && a.input == "" {
			// no movement
		}
		// update doc searcher word for highlighting (already same object)
	}
	if a.inputMode == "markpattern" && a.search != nil {
		// not incremental?
	}
}

func (a *App) inputPrev() {
	// candidates or history
	if a.inputMode == "viewmode" {
		names := a.cfg.modeNames()
		if len(names) > 0 {
			// cycle previous
			idx := indexOfString(names, a.input)
			if idx <= 0 { idx = len(names) } 
			a.input = names[idx-1]
		}
		return
	}
	if a.inputMode == "convert" {
		cands := []string{"align", "es", "raw"}
		idx := indexOfString(cands, a.input)
		if idx <= 0 { idx = len(cands) }
		a.input = cands[idx-1]
		return
	}
	if len(a.history) == 0 { return }
	if a.histIdx > 0 { a.histIdx-- }
	if a.histIdx < len(a.history) {
		a.input = a.history[a.histIdx]
		doc := a.currentDoc()
		a.afterInputChange(doc)
	}
}
func (a *App) inputNext() {
	if a.inputMode == "viewmode" {
		names := a.cfg.modeNames()
		if len(names) > 0 {
			idx := indexOfString(names, a.input)
			if idx < 0 { a.input = names[0] } else if idx+1 < len(names) { a.input = names[idx+1] } else { a.input = names[0] }
		}
		return
	}
	if a.inputMode == "convert" {
		cands := []string{"align", "es", "raw"}
		idx := indexOfString(cands, a.input)
		if idx < 0 { a.input = cands[0] } else { a.input = cands[(idx+1)%len(cands)] }
		return
	}
	if len(a.history) == 0 { return }
	if a.histIdx < len(a.history) {
		a.histIdx++
		if a.histIdx < len(a.history) {
			a.input = a.history[a.histIdx]
		} else {
			// original Down after Up kept previous? We'll keep current input if at end
			// Based on probe: after history beta, Down kept beta. So don't clear.
			a.histIdx = len(a.history) - 1
			if a.histIdx >= 0 { a.input = a.history[a.histIdx] }
		}
		doc := a.currentDoc()
		a.afterInputChange(doc)
	}
}
func indexOfString(s []string, v string) int {
	for i, x := range s { if x == v { return i } }
	return -1
}

func (a *App) submitInput(doc *Document) {
	mode := a.inputMode
	input := a.input
	a.inputMode = ""
	a.input = ""
	if doc == nil { return }
	// history for search-like
	if mode == "search" || mode == "backsearch" || mode == "filter" || mode == "markpattern" {
		if input != "" {
			// avoid duplicate last?
			if len(a.history) == 0 || a.history[len(a.history)-1] != input {
				a.history = append(a.history, input)
			}
		}
	}
	defer func() { a.search = nil }()
	switch mode {
	case "search", "backsearch":
		s := a.searcherFor(doc)
		s.Word = input
		s.compile()
		if input == "" { return }
		if s.Incsearch {
			// already positioned by incsearch; Enter does nothing extra (except if ...?)
			return
		}
		backward := mode == "backsearch"
		// initial search inclusive from input start
		// Our doSearch fromStart uses inputStartDoc set at startSearch
		// Temporarily set a.inputStartDoc (still stored)
		if !a.doSearch(doc, s, backward, true) {
			a.message = fmt.Sprintf("search:not found:%s", input)
		}
	case "filter":
		if input == "" { return }
		s := a.searcherFor(doc)
		// filter uses its own search settings snapshot
		fs := *s
		fs.Word = input
		fs.compile()
		a.createFilter(doc, &fs)
	case "markpattern":
		if input == "" { return }
		s := a.searcherFor(doc)
		ms := *s
		ms.Word = input
		ms.compile()
		count := 0
		for i := 0; i < doc.effCount(); i++ {
			if ms.match(doc.effLineRaw(i)) {
				rawIdx := i + doc.Settings.SkipLines
				doc.Marks[rawIdx] = true
				count++
			}
		}
		a.message = fmt.Sprintf("Added %d marks", count)
	case "goto":
		msg := a.gotoLine(doc, input)
		a.message = msg
	case "header":
		n, err := strconv.Atoi(strings.TrimSpace(input))
		if err != nil {
			a.message = "Set header lines: invalid number"
			return
		}
		doc.Settings.Header = n
		doc.cacheKey = ""
		// adjust top: BodyVis recomputed; if Top was 0 keep - layout body starts at header
		// Original: setting header moves top such that body starts after header if at top
		// Our Top is in BodyVis coordinates, so unchanged is fine (BodyVis starts at header)
		a.message = fmt.Sprintf("Set header lines %d", n)
	case "tabwidth":
		n, err := strconv.Atoi(strings.TrimSpace(input))
		if err != nil {
			a.message = "invalid number"
			return
		}
		doc.Settings.TabWidth = n
		doc.cacheKey = ""
		a.message = fmt.Sprintf("Set tab width %d", n)
	case "skiplines":
		n, err := strconv.Atoi(strings.TrimSpace(input))
		if err != nil {
			a.message = "invalid number"
			return
		}
		doc.Settings.SkipLines = n
		doc.Top = 0
		doc.cacheKey = ""
		a.message = fmt.Sprintf("Set skip lines %d", n)
	case "delimiter":
		// input may be escaped sequences like \t ?
		d := interpretDelimiter(input)
		doc.Settings.ColumnDelimiter = d
		doc.cacheKey = ""
		a.message = fmt.Sprintf("Set delimiter %s", input)
		// original message uses input as typed? For "," it was "Set delimiter ,"
		if d != input {
			// e.g. \t displays? keep original typed in message? unknown; use d if diff?
			a.message = fmt.Sprintf("Set delimiter %s", d)
			// redo to match simple case
			if input == "," || len(input) <= 2 { a.message = fmt.Sprintf("Set delimiter %s", input) }
		}
	case "multicolor":
		if input == "" {
			doc.Settings.MultiColors = nil
		} else {
			parts := strings.Split(input, ",")
			for i := range parts { parts[i] = strings.TrimSpace(parts[i]) }
			doc.Settings.MultiColors = parts
		}
		doc.cacheKey = ""
		a.message = fmt.Sprintf("Set multicolor strings [%s]", strings.Join(doc.Settings.MultiColors, " "))
		// Original format: [1] for single, Go slice formatting [%s join with space] matches fmt %v of slice
		// Use that:
		a.message = fmt.Sprintf("Set multicolor strings %v", doc.Settings.MultiColors)
	case "jumptarget":
		a.setJumpTarget(doc, input)
	case "verticalheader":
		n, err := strconv.Atoi(strings.TrimSpace(input))
		if err != nil { a.message = "invalid number"; return }
		doc.Settings.VerticalHeader = n
		doc.cacheKey = ""
		a.message = fmt.Sprintf("Set vertical header %d", n)
	case "headercolumn":
		n, err := strconv.Atoi(strings.TrimSpace(input))
		if err != nil { a.message = "invalid number"; return }
		doc.Settings.HeaderColumn = n
		a.message = fmt.Sprintf("Set vertical header column %d", n)
	case "viewmode":
		if input == "" { return }
		// apply mode if exists
		if _, ok := a.cfg.Modes[input]; ok || input == "general" {
			if input != "general" {
				newSettings, _ := a.cfg.settingsForMode(doc.Settings, input)
				// Preserve some runtime? original replaces general settings with mode's (base config general + mode)
				// Start from cfg base settings
				base := a.cfg.Settings
				ns, _ := a.cfg.settingsForMode(base, input)
				newSettings = ns
				doc.Settings = newSettings
				// reapply CLI flags? Skip lines etc? Keep existing skip/jump?
			} else {
				doc.Settings = a.cfg.Settings
			}
			doc.cacheKey = ""
			doc.Top = 0
			a.message = fmt.Sprintf("Set mode %s", input)
		} else {
			a.message = fmt.Sprintf("Set mode %s", input)
		}
	case "convert":
		doc.Settings.Converter = input
		doc.cacheKey = ""
		a.message = fmt.Sprintf("Set %s converter", input)
	case "sectiondelimiter":
		doc.Settings.SectionDelimiter = input
		a.message = fmt.Sprintf("Set section delimiter %s", input)
		// original message? unknown; leave
	case "sectionstart":
		n, err := strconv.Atoi(strings.TrimSpace(input))
		if err != nil { a.message = "invalid number"; return }
		// SectionStart in Settings? we don't have field; store in ... use a doc field? Add via Settings? Use JumpTarget hack? Keep in message only
		_ = n
		a.message = fmt.Sprintf("Set section start %d", n)
	case "sectionnum":
		n, err := strconv.Atoi(strings.TrimSpace(input))
		if err != nil { a.message = "invalid number"; return }
		doc.Settings.SectionHeaderNum = n
		a.message = fmt.Sprintf("Set section header number %d", n)
	case "watchinterval":
		n, err := strconv.Atoi(strings.TrimSpace(input))
		if err != nil { a.message = "invalid number"; return }
		doc.WatchInterval = n
		doc.WatchMode = true
		if n == 0 { doc.WatchMode = false }
		a.message = fmt.Sprintf("Set watch interval %d", n)
	case "savefile":
		if input == "" { return }
		// write doc raw lines to file
		content := strings.Join(doc.RawLines, "\n")
		if len(doc.RawLines) > 0 { content += "\n" }
		if err := writeFile(input, content); err != nil {
			a.message = fmt.Sprintf("save failed %s", input)
		} else {
			a.saved = true
			// status left for stdin doc will show name? Original status after save: "(STDIN):saved /path"
			a.message = fmt.Sprintf("saved %s", input)
		}
	case "marknumber":
		a.sidebar = 0
		for _, d := range a.allDocs() { d.cacheKey = "" }
		n, err := strconv.Atoi(strings.TrimSpace(input))
		if err != nil {
			if input == "" {
				// if just Enter with no input, maybe go to mark 0? original prompt shows 0/1 selected in sidebar
				// Use currently highlighted mark index 0
				n = 0
			} else {
				a.message = "invalid number"; return
			}
		}
		marks := sortedMarks(doc)
		if n >= 0 && n < len(marks) {
			m := marks[n]
			li := a.layout(doc)
			msg := a.gotoTarget(doc, li, m+1, fmt.Sprintf("Moved to line %d", m+1))
			a.message = msg
		} else if len(marks) == 0 {
			// no marks
		} else {
			// treat input as line number? original "," input number is mark number index
		}
	case "writeandquit":
		// parse before/after
		bStr, aStr := parseWriteAndQuit(input)
		a.exitWriteBefore = bStr
		a.exitWriteAfter = aStr
		a.quitWithWrite(doc)
	}
}

func parseWriteAndQuit(input string) (int, int) {
	input = strings.TrimSpace(input)
	if input == "" { return 0, 0 }
	parts := strings.Split(input, ":")
	var b, aft int
	if len(parts) >= 1 { b, _ = strconv.Atoi(strings.TrimSpace(parts[0])) }
	if len(parts) >= 2 { aft, _ = strconv.Atoi(strings.TrimSpace(parts[1])) }
	return b, aft
}

func writeFile(path string, content string) error {
	return os.WriteFile(path, []byte(content), 0644)
}

func interpretDelimiter(input string) string {
	// handle \t, \s etc as original might
	switch input {
	case "\\t":
		return "\t"
	case "\\s":
		return " "
	}
	// unicode escape?
	if strings.HasPrefix(input, "\\u") {
		if n, err := strconv.ParseInt(input[2:], 16, 32); err == nil {
			return string(rune(n))
		}
	}
	return input
}

func (a *App) setJumpTarget(doc *Document, input string) {
	input = strings.TrimSpace(input)
	li := a.layout(doc)
	// validate
	valid := false
	var msg string
	if input == "section" {
		valid = true
		msg = fmt.Sprintf("Set JumpTarget %s", input)
	} else if strings.HasSuffix(input, "%") {
		if f, err := strconv.ParseFloat(strings.TrimSuffix(input, "%"), 64); err == nil {
			if f >= 0 && f <= 100 {
				// offset within body?
				valid = true
				msg = fmt.Sprintf("Set JumpTarget %s", input)
			}
		}
	} else if strings.HasPrefix(input, ".") {
		if f, err := strconv.ParseFloat(input, 64); err == nil && f >= 0 && f <= 1 {
			valid = true
			msg = fmt.Sprintf("Set JumpTarget %s", input)
		}
	} else {
		if n, err := strconv.Atoi(input); err == nil {
			if n >= 0 && n < li.BodyRows {
				valid = true
				msg = fmt.Sprintf("Set JumpTarget %d", n)
			} else {
				msg = fmt.Sprintf("Set JumpTarget %s: value out of range", input)
				a.message = msg
				return
			}
		}
	}
	if !valid {
		// numeric invalid etc
		if _, err := strconv.Atoi(input); err != nil && !strings.HasSuffix(input, "%") && !strings.HasPrefix(input, ".") && input != "section" {
			a.message = fmt.Sprintf("Set JumpTarget %s: invalid number", input)
			return
		}
		a.message = fmt.Sprintf("Set JumpTarget %s: value out of range", input)
		return
	}
	doc.Settings.JumpTarget = input
	a.message = msg
}

func (a *App) createFilter(doc *Document, s *Searcher) {
	var lines []string
	for _, raw := range doc.RawLines {
		if s.match(raw) {
			lines = append(lines, raw)
		}
	}
	patternDisplay := s.Word
	if s.NonMatch { patternDisplay = "!" + s.Word }
	name := fmt.Sprintf("filter:%s", patternDisplay)
	nd := newDocument(name, lines, doc.Settings)
	nd.IsFilter = true
	nd.ParentIdx = a.indexOfDoc(doc)
	// nd settings: search word for highlight
	nd.Top = 0
	// add to docs
	a.docs = append(a.docs, nd)
	a.cur = len(a.docs) - 1
	// set searcher for filter doc
	fs := *s
	a.searchByDoc[nd] = &fs
	// ensure highlighting uses filter word (not nonmatch for highlight)
	// For non-match, highlight should not highlight? original filter:!beta status search:!beta; highlight maybe none.
	a.logf("filter %s", name)
}

var _ = regexp.MustCompile
EOF"}

