func (a *App) handleMouse(ev *tcell.EventMouse) {
	doc := a.currentDoc()
	if doc == nil { return }
	btn := ev.Buttons()
	if btn&tcell.WheelDown != 0 {
		a.message = ""
		a.moveDown(doc, doc.Settings.VScrollLines)
		if doc.Settings.VScrollLines == 0 { a.moveDown(doc, 1) }
	}
	if btn&tcell.WheelUp != 0 {
		a.message = ""
		n := doc.Settings.VScrollLines
		if n == 0 { n = 1 }
		a.moveUp(doc, n)
	}
	// clicks: column mode selection?
	if btn&tcell.Button1 != 0 && doc.Settings.ColumnMode {
		x, y := ev.Position()
		_ = x; _ = y
	}
}

