func (doc *Document) displayName() string {
	if doc.Caption != "" { return doc.Caption }
	return doc.Name
}

func hscrollAmount(v string, width int) int {
	v = strings.TrimSpace(v)
	if v == "" { return 0 }
	if strings.HasSuffix(v, "%") {
		f, err := strconv.ParseFloat(strings.TrimSuffix(v, "%"), 64)
		if err != nil { return 0 }
		return int(float64(width) * f / 100.0)
	}
	if strings.HasPrefix(v, ".") {
		f, err := strconv.ParseFloat(v, 64)
		if err != nil { return 0 }
		return int(float64(width) * f)
	}
	n, err := strconv.Atoi(v)
	if err != nil { return 0 }
	return n
}

func (a *App) columnRight(doc *Document) {
	li := a.layout(doc)
	topDoc := doc.topDocIdx(li)
	// Determine max columns among visible lines? Use top/header line? Original error when first line has no column.
	// Use the top line's fields to decide, but also check all lines? Capture for csv: works.
	// If no line in current view has > cursor+1 columns, error.
	found := false
	// check lines in view
	for _, v := range li.BodyVis {
		full := doc.fullCells(v.DocIdx)
		ranges := splitFieldsRange(full, doc.Settings.ColumnDelimiter)
		if len(ranges) > doc.ColumnCursor+1 {
			found = true
			break
		}
	}
	// Also check header lines
	if !found {
		for _, v := range li.FixedHdrVis {
			full := doc.fullCells(v.DocIdx)
			if len(splitFieldsRange(full, doc.Settings.ColumnDelimiter)) > doc.ColumnCursor+1 { found = true }
		}
	}
	_ = topDoc
	if !found {
		// cycle or error? If cursor at last and cycling enabled, wrap to 0 unless DisableColumnCycle
		// But original for single-column gave error "column not found".
		// Determine max columns overall
		maxCols := 0
		for i := 0; i < doc.effCount(); i++ {
			full := doc.fullCells(i)
			r := splitFieldsRange(full, doc.Settings.ColumnDelimiter)
			if len(r) > maxCols { maxCols = len(r) }
		}
		if maxCols <= 1 {
			a.message = "Cannot move column: column not found"
			return
		}
		if !a.cfg.DisableColumnCycle {
			doc.ColumnCursor = 0
			return
		}
		a.message = "Cannot move column: column not found"
		return
	}
	doc.ColumnCursor++
	// if beyond max for some lines fine. Wrap if exceeds global max?
	maxCols := 0
	for i := 0; i < doc.effCount(); i++ {
		r := splitFieldsRange(doc.fullCells(i), doc.Settings.ColumnDelimiter)
		if len(r) > maxCols { maxCols = len(r) }
	}
	if doc.ColumnCursor >= maxCols {
		if !a.cfg.DisableColumnCycle {
			doc.ColumnCursor = 0
		} else {
			doc.ColumnCursor = maxCols - 1
		}
	}
}

func (a *App) columnLeft(doc *Document) {
	if doc.ColumnCursor > 0 {
		doc.ColumnCursor--
		return
	}
	// cycle to last?
	maxCols := 0
	for i := 0; i < doc.effCount(); i++ {
		r := splitFieldsRange(doc.fullCells(i), doc.Settings.ColumnDelimiter)
		if len(r) > maxCols { maxCols = len(r) }
	}
	if maxCols <= 1 {
		a.message = "Cannot move column: column not found"
		return
	}
	if !a.cfg.DisableColumnCycle {
		doc.ColumnCursor = maxCols - 1
	}
}

func (a *App) toggleMark(doc *Document, add bool) {
	li := a.layout(doc)
	topDocEff := doc.topDocIdx(li)
	rawIdx := topDocEff + doc.Settings.SkipLines
	// focus line if jump target? Marks act on top line (observed)
	if add {
		doc.Marks[rawIdx] = true
		a.message = fmt.Sprintf("Marked to line %d", rawIdx+1)
	} else {
		if doc.Marks[rawIdx] {
			delete(doc.Marks, rawIdx)
		}
		a.message = fmt.Sprintf("Remove the mark at line %d", rawIdx+1)
	}
}

func (a *App) moveMark(doc *Document, forward bool) {
	marks := sortedMarks(doc)
	if len(marks) == 0 { return }
	li := a.layout(doc)
	focusEff := a.focusDocIdx(doc, li)
	focusRaw := focusEff + doc.Settings.SkipLines
	if forward {
		for _, m := range marks {
			if m > focusRaw {
				a.gotoTarget(doc, li, m+1, fmt.Sprintf("Moved to line %d", m+1))
				a.message = fmt.Sprintf("Moved to line %d", m+1)
				return
			}
		}
	} else {
		for i := len(marks) - 1; i >= 0; i-- {
			if marks[i] < focusRaw {
				m := marks[i]
				a.gotoTarget(doc, li, m+1, fmt.Sprintf("Moved to line %d", m+1))
				a.message = fmt.Sprintf("Moved to line %d", m+1)
				return
			}
		}
	}
}

func (a *App) nextSection(doc *Document) {
	li := a.layout(doc)
	// If no section delimiter, Space behaves like page down (observed)
	if doc.Settings.SectionDelimiter == "" {
		a.movePageDown(doc)
		return
	}
	curEff := doc.topDocIdx(li)
	if doc.Settings.SectionHeader {
		// top may be section start; next from cur
	}
	if nxt, ok := doc.nextSection(curEff); ok {
		doc.Top = a.docEffToBodyVis(doc, li, nxt)
	} else {
		a.message = "No more next sections"
		a.movePageDown(doc)
	}
}
func (a *App) prevSection(doc *Document) {
	li := a.layout(doc)
	curEff := doc.topDocIdx(li)
	if prv, ok := doc.prevSection(curEff); ok {
		doc.Top = a.docEffToBodyVis(doc, li, prv)
	} else {
		a.message = "No more previous sections"
	}
}
func (a *App) lastSection(doc *Document) {
	li := a.layout(doc)
	if last, ok := doc.lastSection(); ok {
		doc.Top = a.docEffToBodyVis(doc, li, last)
	}
}
func (a *App) docEffToBodyVis(doc *Document, li layoutInfo, eff int) int {
	for i, v := range li.BodyVis {
		if v.DocIdx >= eff { return i }
	}
	return len(li.BodyVis) - 1
}

func (a *App) nextDoc(dir int) {
	if a.special != nil { a.special = nil; return }
	if len(a.docs) == 0 { return }
	a.cur += dir
	if a.cur >= len(a.docs) { a.cur = 0 }
	if a.cur < 0 { a.cur = len(a.docs) - 1 }
}

func (a *App) closeCurrentDoc() {
	if a.special != nil { a.special = nil; return }
	if len(a.docs) <= 1 {
		a.message = "only this document"
		return
	}
	oldIdx := a.cur
	a.docs = append(a.docs[:oldIdx], a.docs[oldIdx+1:]...)
	if a.cur >= len(a.docs) { a.cur = len(a.docs) - 1 }
	if a.cur < 0 { a.cur = 0 }
	nd := a.docs[a.cur]
	// message as original (referring to new current)
	a.message = fmt.Sprintf("close [%d]%s", a.cur, nd.displayName())
}

func (a *App) closeAllFilters() {
	var removed []string
	var kept []*Document
	for _, d := range a.docs {
		if d.IsFilter {
			removed = append(removed, d.Name)
		} else {
			kept = append(kept, d)
		}
	}
	if len(removed) == 0 {
		// what message? probe later; for now none
		return
	}
	a.docs = kept
	if a.cur >= len(a.docs) { a.cur = len(a.docs) - 1 }
	if a.cur < 0 { a.cur = 0 }
	a.message = fmt.Sprintf("close %s", removed[len(removed)-1])
}

func (a *App) toggleSidebar(kind int, name string) {
	if a.sidebar == kind {
		a.sidebar = 0
		a.message = "Sidebar hidden"
	} else {
		a.sidebar = kind
		a.sidebarTop = 0
		a.message = fmt.Sprintf("Sidebar %s visible", name)
	}
	if a.screen != nil {
		// force re-layout
		for _, d := range a.allDocs() { d.cacheKey = "" }
	}
}

func (a *App) showHelp() {
	if a.helpDoc == nil {
		text := generateHelpDocText(a.cfg.KeyBind)
		lines := splitLines([]byte(text))
		settings := a.currentDoc().Settings
		// Help doc has header 2
		settings.Header = 2
		settings.LineNumMode = false
		hd := newDocument("Help", lines, settings)
		hd.IsHelp = true
		hd.Top = 0 // BodyVis will be lines from 2
		a.helpDoc = hd
	}
	if a.special == a.helpDoc {
		a.special = nil
		return
	}
	a.returnTo = a.currentDoc()
	a.special = a.helpDoc
	a.helpDoc.cacheKey = ""
}

func (a *App) showLog() {
	if a.logDoc == nil {
		settings := a.currentDoc().Settings
		ld := newDocument("Log", append([]string{}, a.logLines...), settings)
		ld.IsLog = true
		ld.FollowMode = true
		a.logDoc = ld
	} else {
		a.logDoc.setLines(append([]string{}, a.logLines...))
		a.logDoc.cacheKey = ""
	}
	if a.special == a.logDoc {
		a.special = nil
		return
	}
	a.returnTo = a.currentDoc()
	a.special = a.logDoc
	a.moveBottom(a.logDoc)
}

func (a *App) saveBuffer(doc *Document) {
	if doc.Seekable {
		a.message = "Cannot save seekable files"
		return
	}
	a.startInput("savefile", "")
}

func (a *App) editDoc(doc *Document) {
	editor := os.Getenv("EDITOR")
	if editor == "" { editor = "vi" }
	if doc.FilePath == "" {
		return
	}
	a.screen.Fini()
	cmd := exec.Command(editor, doc.FilePath)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	_ = cmd.Run()
	// reinit screen
	_ = a.screen.Init()
	a.reloadDoc(doc, true)
}

func (a *App) quitApp(write bool) {
	_ = write
	// if writeOriginal on normal quit? original: no output
	a.quit = true
}

func (a *App) quitWithWrite(doc *Document) {
	li := a.layout(doc)
	if a.writeOriginal || a.cfg.IsWriteOriginal {
		before := a.cfg.BeforeWriteOriginal
		after := a.cfg.AfterWriteOriginal
		if a.exitWriteBefore != 0 { before = a.exitWriteBefore }
		if a.exitWriteAfter != 0 { after = a.exitWriteAfter }
		if before == 0 && after == 0 {
			// original lines in view (dedup doc lines)
			seen := map[int]bool{}
			var out []string
			// headers
			for _, v := range li.FixedHdrVis {
				rawIdx := v.DocIdx + doc.Settings.SkipLines
				if rawIdx >= 0 && rawIdx < len(doc.RawLines) && !seen[rawIdx] {
					out = append(out, doc.RawLines[rawIdx]); seen[rawIdx] = true
				}
			}
			count := 0
			for visIdx := doc.Top; count < li.BodyRows; visIdx++ {
				if visIdx < 0 { count++; continue }
				if visIdx >= len(li.BodyVis) { break }
				v := li.BodyVis[visIdx]
				rawIdx := v.DocIdx + doc.Settings.SkipLines
				if rawIdx >= 0 && rawIdx < len(doc.RawLines) && !seen[rawIdx] {
					out = append(out, doc.RawLines[rawIdx]); seen[rawIdx] = true
				}
				count++
			}
			a.pendingOutput = out
		} else {
			topRaw := doc.topDocIdx(li) + doc.Settings.SkipLines
			start := topRaw - before
			if start < 0 { start = 0 }
			var out []string
			for i := start; i < start+before+after && i < len(doc.RawLines); i++ {
				out = append(out, doc.RawLines[i])
			}
			a.pendingOutput = out
		}
	} else {
		// screen text, shifted by exitWriteBefore
		before := a.exitWriteBefore
		// cfg before as fallback if exit flags correspond? flags already mapped to exitWriteBefore
		savedTop := doc.Top
		doc.Top = doc.Top - before
		li2 := a.layout(doc)
		out := a.screenTextLines(doc, li2)
		doc.Top = savedTop
		// screenTextLines includes header vis etc; for Q it previously matched: headers? Keep.
		// But when before>0, headers duplication? At top large no header.
		a.pendingOutput = out
	}
	a.quit = true
}

