func helpFunc(cmd *cobra.Command, args []string) {
	out := cmd.OutOrStdout()
	if cmd == rootCmd || cmd.Name() == "ov" && cmd.Parent() == nil {
		fmt.Fprint(out, rootHelpText)
		return
	}
	// subcommand (completion etc.)
	long := cmd.Long
	if long == "" {
		long = cmd.Short
	}
	if long != "" {
		fmt.Fprint(out, long+"\n\n")
	}
	fmt.Fprintf(out, "Usage:\n  %s [flags] [FILE]...\n\nFlags:\n%s", cmd.CommandPath(), flagsTable)
}

func isTerminal(fd uintptr) bool {
	return term.IsTerminal(int(fd))
}

func runRoot(cmd *cobra.Command, args []string) error {
	// load config
	cl := loadConfig(flags.config, flags.debug)
	cl.report(flags.debug)
	cfg := cl.cfg
	if flags.debug {
		cfg.Debug = true
	}

	// standalone outputs in precedence order
	if flags.version {
		fmt.Fprintf(cmd.OutOrStdout(), "ov version %s rev:%s\n", Version, Revision)
		return nil
	}
	if flags.helpKey {
		fmt.Fprint(cmd.OutOrStdout(), generateHelpKey(cfg.KeyBind))
		return nil
	}
	if flags.listViewModes {
		for _, n := range cfg.modeNames() {
			fmt.Fprintln(cmd.OutOrStdout(), n)
		}
		return nil
	}
	if flags.completion != "" {
		switch flags.completion {
		case "bash":
			return cmd.Root().GenBashCompletion(cmd.OutOrStdout())
		case "zsh":
			return cmd.Root().GenZshCompletion(cmd.OutOrStdout())
		case "fish":
			return cmd.Root().GenFishCompletion(cmd.OutOrStdout())
		case "powershell":
			return cmd.Root().GenPowerShellCompletion(cmd.OutOrStdout())
		default:
			return errors.New("requires one of the arguments bash/zsh/fish/powershell")
		}
	}

	// apply config + CLI flags to settings
	applyFlagsToConfig(cmd, cfg)

	// non-TTY passthrough
	if !isTerminal(os.Stdout.Fd()) && !flags.forceScreen {
		if len(args) == 0 && isTerminal(os.Stdin.Fd()) {
			return errors.New("missing file")
		}
		return passthrough(args)
	}

	// Build app and documents
	app := &App{
		cfg:             cfg,
		load:            cl,
		flags:           &flags,
		searchByDoc:     map[*Document]*Searcher{},
		keyMap:          buildKeyMap(cfg.KeyBind),
		writeOriginal:   cfg.IsWriteOriginal,
		exitWriteBefore: flags.exitWriteBefore,
		exitWriteAfter:  flags.exitWriteAfter,
	}
	// If exit-write flags not changed but config has before/after, they were applied to cfg; keep app values as flags (0) - quitWithWrite falls back to cfg
	if err := buildDocuments(app, args); err != nil {
		return err
	}
	// initial messages / follow etc handled in App.Run after screen sizing
	return app.run()
}

func applyFlagsToConfig(cmd *cobra.Command, cfg *AppConfig) {
	changed := func(name string) bool {
		fl := cmd.Flags().Lookup(name)
		if fl == nil {
			fl = cmd.PersistentFlags().Lookup(name)
		}
		return fl != nil && fl.Changed
	}
	s := &cfg.Settings
	// view mode first
	modeName := cfg.ViewMode
	if changed("view-mode") || flags.viewMode != "" {
		modeName = flags.viewMode
	}
	if modeName != "" && modeName != "general" {
		if _, ok := cfg.Modes[modeName]; ok {
			ns, _ := cfg.settingsForMode(*s, modeName)
			*s = ns
		}
