	}
	if changed("column-delimiter") {
		s.ColumnDelimiter = flags.columnDelimiter
	}
	if changed("column-mode") {
		s.ColumnMode = flags.columnMode
	}
	if changed("column-rainbow") {
		s.ColumnRainbow = flags.columnRainbow
	}
	if changed("column-width") {
		s.ColumnWidth = flags.columnWidth
	}
	if changed("converter") {
		s.Converter = flags.converter
	}
	if changed("raw") && flags.raw {
		s.Converter = "raw"
	}
	if changed("debug") {
		cfg.Debug = flags.debug
	}
	if changed("disable-column-cycle") {
		cfg.DisableColumnCycle = flags.disableColumnCycle
	}
	if changed("disable-mouse") {
		cfg.DisableMouse = flags.disableMouse
	}
	if changed("header") {
		s.Header = flags.header
	}
	if changed("header-column") {
		s.HeaderColumn = flags.headerColumn
	}
	if changed("hide-other-section") {
		s.HideOtherSection = flags.hideOtherSection
	}
	if changed("hscroll-width") {
		s.HScrollWidth = flags.hscrollWidth
	}
	if changed("jump-target") {
		s.JumpTarget = flags.jumpTarget
	}
	if changed("line-number") {
		s.LineNumMode = flags.lineNumber
	}
	if changed("memory-limit") {
		cfg.MemoryLimit = flags.memoryLimit
	}
	if changed("memory-limit-file") {
		cfg.MemoryLimitFile = flags.memoryLimitFile
	}
	if changed("multi-color") {
		s.MultiColors = flags.multiColor
	}
	if changed("plain") {
		s.Plain = flags.plain
	}
	if changed("ruler") {
		s.Ruler = flags.ruler
	}
	if changed("section-delimiter") {
