func passthrough(args []string) error {
	if len(args) == 0 {
		_, err := io.Copy(os.Stdout, os.Stdin)
		return err
	}
	f, err := os.Open(args[0])
	if err != nil {
		return err
	}
	defer f.Close()
	_, err = io.Copy(os.Stdout, f)
	return err
}

func buildDocuments(app *App, args []string) error {
	settings := app.cfg.Settings
	// exec mode
	if app.flags.exec {
		if len(args) == 0 {
			return errors.New("no arguments to execute")
		}
		return buildExecDocuments(app, args, settings)
	}
	if len(args) == 0 {
		if isTerminal(os.Stdin.Fd()) {
			return errors.New("missing file")
		}
		data, err := io.ReadAll(os.Stdin)
		if err != nil {
			return err
		}
		data = decompressIfNeeded(data, app.flags.skipExtract)
		lines := splitLines(data)
		doc := newDocument("(STDIN)", lines, settings)
		doc.IsStdin = true
		doc.Seekable = false
		if app.flags.caption != "" {
			doc.Caption = app.flags.caption
		}
		app.docs = []*Document{doc}
		app.logf("open (STDIN)")
		finalizeDocs(app)
		return nil
	}
	// files
	var docs []*Document
	for i, path := range args {
		st, err := os.Stat(path)
		if err != nil {
			app.logf("open [%d]%s", i, path)
			continue
		}
		if st.IsDir() {
			app.logf("open [%d]%s", i, path)
			continue
		}
		data, err := os.ReadFile(path)
		if err != nil {
			continue
		}
		data = decompressIfNeeded(data, app.flags.skipExtract)
		lines := splitLines(data)
		doc := newDocument(path, lines, settings)
		doc.FilePath = path
		doc.Seekable = st.Mode().IsRegular()
		doc.lastSize = st.Size()
		doc.lastModUnixNano = st.ModTime().UnixNano()
		if app.flags.caption != "" {
			doc.Caption = app.flags.caption
		}
		docs = append(docs, doc)
		app.logf("open [%d]%s", i, path)
	}
	if len(docs) == 0 {
		// error based on first arg
		first := args[0]
		if st, err := os.Stat(first); err == nil && st.IsDir() {
			return fmt.Errorf("'%s' is a directory", first)
		}
		return fmt.Errorf("'%s' not found", first)
	}
	app.docs = docs
	finalizeDocs(app)
	return nil
}

func finalizeDocs(app *App) {
	f := app.flags
	for _, doc := range app.docs {
		if f.followMode || f.followName {
			doc.FollowMode = true
		}
		if f.followAll {
			doc.FollowAll = true
		}
		if f.followSection {
			doc.FollowSection = true
		}
		if f.watch > 0 {
			doc.WatchMode = true
			doc.WatchInterval = f.watch
		}
		if f.notifyEOF != 0 {
			// Changed detection handled by value; bare sets 1
			doc.NotifyEOF = true
		}
	}
	// follow-name treated as follow mode
	// pattern / filter applied after app starts (needs layout) - store on first doc via app fields? Use a flag in App initial actions
	appInitial.pattern = f.pattern
	appInitial.filter = f.filter
	appInitial.nonMatchFilter = f.nonMatchFilter
}

type appInitialT struct {
	pattern string
	filter string
	nonMatchFilter string
}
var appInitial appInitialT

func buildExecDocuments(app *App, args []string, settings Settings) error {
	cmdName := args[0]
	cmdArgs := args[1:]
	c := exec.Command(cmdName, cmdArgs...)
	var outBuf, errBuf strings.Builder
	c.Stdout = &outBuf
	c.Stderr = &errBuf
	if err := c.Start(); err != nil {
		return fmt.Errorf("command start error: %w", err)
	}
	_ = c.Wait()
	outData := decompressIfNeeded([]byte(outBuf.String()), app.flags.skipExtract)
	outDoc := newDocument(fmt.Sprintf("(%s)STDOUT", cmdName), splitLines(outData), settings)
	outDoc.IsExec = true
	outDoc.ExecCmd = cmdName
	outDoc.Seekable = false
	if app.flags.caption != "" { outDoc.Caption = app.flags.caption }
	app.docs = []*Document{outDoc}
	app.logf("open (%s)STDOUT", cmdName)
	if errBuf.Len() > 0 {
		errData := decompressIfNeeded([]byte(errBuf.String()), app.flags.skipExtract)
		errDoc := newDocument(fmt.Sprintf("(%s)STDERR", cmdName), splitLines(errData), settings)
		errDoc.IsExec = true
		errDoc.ExecCmd = cmdName
		if app.flags.caption != "" { errDoc.Caption = app.flags.caption }
		app.docs = append(app.docs, errDoc)
	}
	finalizeDocs(app)
	return nil
}
