		doc.Settings.JumpTarget = "section"
		a.message = "Set JumpTarget section start"
		return
	}
	offset, ok := parseJumpOffset(input, li.H)
	if !ok { return }
	if offset > li.H-1 {
		a.message = fmt.Sprintf("Set JumpTarget %d: value out of range", offset)
		return
	}
	// current offset
