	if offset == cur && doc.Settings.JumpTarget != "" { return }
	if offset == 0 && doc.Settings.JumpTarget == "" { 
		doc.Settings.JumpTarget = "0"
		return
	}
	doc.Settings.JumpTarget = strconv.Itoa(offset)
	a.message = fmt.Sprintf("Set JumpTarget %d", offset)
}

