	input = strings.TrimSpace(input)
	if input == "" { return 0, false }
	if strings.HasSuffix(input, "%") {
		f, err := strconv.ParseFloat(strings.TrimSuffix(input, "%"), 64)
		if err != nil || f < 0 { return 0, false }
		return int(f/100.0*float64(screenHeight) + 0.5), true
	}
	if strings.HasPrefix(input, ".") {
		digits := strings.TrimPrefix(input, ".")
		dv, err := strconv.ParseFloat(digits, 64)
		if err != nil || dv < 0 { return 0, false }
		v := dv / 10.0
		return int(v*float64(screenHeight) + 0.5), true
	}
	if strings.Contains(input, ".") {
		f, err := strconv.ParseFloat(input, 64)
		if err != nil || f < 0 { return 0, false }
		return int(f + 0.5), true
	}
	n, err := strconv.Atoi(input)
	if err != nil || n < 0 { return 0, false }
	return n, true
}

func (a *App) setJumpTarget(doc *Document, input string) {
	input = strings.TrimSpace(input)
	if input == "" { return }
	li := a.layout(doc)
	if input == "section" {
		if doc.Settings.JumpTarget == "section" { return }
		doc.Settings.JumpTarget = "section"
		a.message = "Set JumpTarget section start"
		return
	}
	offset, ok := parseJumpOffset(input, li.H)
	if !ok { return }
	if offset > li.H-1 {
