{"command":"cat > /tmp/patch_watch.py << 'PY'
import pathlib
p=pathlib.Path("app.go"); t=p.read_text()
# Add lastWatch field
t=t.replace("	lastFollowCheck time.Time\n", "	lastFollowCheck time.Time\n	lastWatch time.Time\n")
# periodic rewrite for watch/follow-all
old_start=t.find("func (a *App) periodic() {")
old_end=t.find("// movement helpers", old_start)
old=t[old_start:old_end]
new=r'''func (a *App) periodic() {
	now := time.Now()
	if a.lastWatch.IsZero() { a.lastWatch = now }
	doc := a.currentDoc()
	if doc == nil { return }
	// Follow-all: check all docs for changes and switch to most recently changed
	if doc.FollowAll {
		for i, d := range a.docs {
			if d.FilePath == "" { continue }
			if st, err := os.Stat(d.FilePath); err == nil {
				if st.ModTime().UnixNano() != d.lastModUnixNano || st.Size() != d.lastSize {
					a.reloadDoc(d, true)
					a.cur = i
					a.moveBottom(d)
					doc = d
				}
			}
		}
	}
	// watch mode: append reload at interval
	interval := doc.WatchInterval
	if interval <= 0 { interval = 1 }
	if doc.WatchMode && now.Sub(a.lastWatch) >= time.Duration(interval)*time.Second {
		a.lastWatch = now
		a.watchReload(doc)
		return
	}
	if now.Sub(a.lastFollowCheck) < 200*time.Millisecond { return }
	a.lastFollowCheck = now
	if doc.FollowMode || doc.FollowSection {
		if doc.FilePath != "" {
			if st, err := os.Stat(doc.FilePath); err == nil {
				if st.ModTime().UnixNano() != doc.lastModUnixNano || st.Size() != doc.lastSize {
					a.reloadDoc(doc, true)
					a.moveBottom(doc)
				}
			}
		}
		if doc.IsLog {
			if len(a.logLines) != len(doc.RawLines) {
				doc.setLines(append([]string{}, a.logLines...))
				doc.cacheKey = ""
				a.moveBottom(doc)
			}
		}
	}
	// Log doc sync even when not follow
	if doc.IsLog && len(a.logLines) != len(doc.RawLines) {
		doc.setLines(append([]string{}, a.logLines...))
		doc.cacheKey = ""
	}
}

func (a *App) watchReload(doc *Document) {
	var newLines []string
	if doc.FilePath != "" {
		data, err := readFileBytes(doc.FilePath)
		if err != nil { return }
		data = decompressIfNeeded(data, a.flags.skipExtract)
		newLines = splitLines(data)
		if st, err := os.Stat(doc.FilePath); err == nil {
			doc.lastSize = st.Size()
			doc.lastModUnixNano = st.ModTime().UnixNano()
		}
		a.message = fmt.Sprintf("reload file %s", doc.FilePath)
	} else if doc.IsExec && doc.ExecCmd != "" {
		// re-run command with original args not stored; store args in ExecCmd? Exec docs only have name.
		// Re-running is handled for file docs mainly; exec watch will re-run using stored command line if available.
		return
	} else {
		return
	}
	oldCount := len(doc.RawLines)
	combined := append([]string{}, doc.RawLines...)
	combined = append(combined, "")
	combined = append(combined, newLines...)
	topEff := oldCount + 1 - doc.Settings.SkipLines
	doc.setLines(combined)
	doc.cacheKey = ""
	// move to first line of newly appended content
	li := a.layout(doc)
	idx := -1
	for i, v := range li.BodyVis {
		if v.DocIdx >= topEff { idx = i; break }
	}
	if idx >= 0 { doc.Top = idx }
}

'''
t=t[:old_start]+new+t[old_end:]
p.write_text(t)
PY
